// ── RALLI LOGO ─────────────────────────────────────────────
// Official lockup embedded as data URIs so the logo renders
// from the JS bundle and never depends on static file serving.
const _LOGO_DARK  = "data:image/png;base64,";
const _LOGO_LIGHT = "data:image/png;base64,";

function RalliLogo({ height = 32, light = false }) {
  return (
    <img
      src={light ? _LOGO_LIGHT : _LOGO_DARK}
      alt="ralli"
      draggable={false}
      style={{ height, width: "auto", display: "block", flexShrink: 0 }}
    />
  );
}

// ── SHARED COMPONENTS ──────────────────────────────────────

function Avatar({ initials, size = 32, color = C.orange, bg }) {
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%",
      background: bg || color + "22",
      border: `2px solid ${color}44`,
      display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: size * 0.35, fontWeight: 700, color,
      flexShrink: 0,
    }}>
      {initials}
    </div>
  );
}

function ProgressBar({ value, max = 100, color = C.orange, height = 6, trackColor = C.muted }) {
  const pct = Math.min((value / max) * 100, 100);
  return (
    <div style={{ background: trackColor, borderRadius: 99, height, overflow: "hidden" }}>
      <div style={{
        height: "100%", width: `${pct}%`, borderRadius: 99,
        background: color, transition: "width 0.5s ease",
      }} />
    </div>
  );
}

// Leadership Dashboard — Actionable KPI Cards: Card now optionally forwards
// a11y/interaction props (role, tabIndex, onKeyDown, focus/hover handlers) so
// a Card can become keyboard-activatable without a second, parallel
// clickable-card component. All new props are optional and default to
// undefined, so every existing <Card> usage (the overwhelming majority,
// non-interactive) renders exactly as before.
function Card({ children, style = {}, onClick, id, role, tabIndex, onKeyDown, onMouseEnter, onMouseLeave, onFocus, onBlur, ariaLabel }) {
  return (
    <div
      id={id} onClick={onClick} role={role} tabIndex={tabIndex} onKeyDown={onKeyDown}
      onMouseEnter={onMouseEnter} onMouseLeave={onMouseLeave} onFocus={onFocus} onBlur={onBlur}
      aria-label={ariaLabel}
      style={{
        background: C.white, borderRadius: 16,
        border: `1px solid ${C.border}`,
        boxShadow: C.shadowSm,
        padding: 20, ...style,
      }}
    >
      {children}
    </div>
  );
}

// ── SHARED LOADING / EMPTY / ERROR STATES ────────────────────────────────────
// Reusable across all first-load real-user screens.
// Demo mode: these components are never shown (data is always present from seed).

function LoadingState({ rows = 3, message = "Loading…" }) {
  return (
    <>
      <style>{`@keyframes ralliShimmer{0%{background-position:-600px 0}100%{background-position:600px 0}}`}</style>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {message && <div style={{ fontSize: 13, color: C.textMuted, marginBottom: 4 }}>{message}</div>}
        {Array.from({ length: rows }, (_, i) => (
          <div key={i} style={{
            height: 52, borderRadius: 12,
            background: "linear-gradient(90deg, #f5f5f4 25%, #ece9e4 50%, #f5f5f4 75%)",
            backgroundSize: "1200px 100%",
            animation: "ralliShimmer 1.5s ease-in-out infinite",
            opacity: Math.max(0.4, 1 - i * 0.18),
          }} />
        ))}
      </div>
    </>
  );
}

function EmptyState({ icon = "📭", title = "Nothing here yet", message = "", action = null }) {
  return (
    <div style={{
      background: C.white, borderRadius: 14, border: `1px solid ${C.border}`,
      display: "flex", flexDirection: "column", alignItems: "center",
      justifyContent: "center", padding: "56px 40px", textAlign: "center", gap: 12,
    }}>
      <div style={{
        width: 52, height: 52, borderRadius: 14, background: C.orangeLight,
        display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22,
      }}>{icon}</div>
      <div style={{ fontSize: 16, fontWeight: 800, color: C.text }}>{title}</div>
      {message && <p style={{ margin: 0, fontSize: 13, color: C.textSub, maxWidth: 320, lineHeight: 1.6 }}>{message}</p>}
      {action}
    </div>
  );
}

