// Inline tooltip helper — renders an ℹ badge with a hover tooltip. Also
// toggles on click/tap (in addition to hover) so it works as an explanation
// affordance on touch devices, which never fire hover — used e.g. by the
// Assign modal's "already has an active assignment" row explanation.
function InfoTooltip({ text }) {
  const [show, setShow] = useState(false);
  return (
    <span style={{ position: "relative", display: "inline-flex", alignItems: "center" }}>
      <span
        onMouseEnter={() => setShow(true)}
        onMouseLeave={() => setShow(false)}
        onClick={(e) => { e.stopPropagation(); setShow(s => !s); }}
        role="button"
        tabIndex={0}
        aria-label="More info"
        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.stopPropagation(); setShow(s => !s); } }}
        style={{ width: 15, height: 15, borderRadius: "50%", background: C.muted, color: C.textMuted, fontSize: 9, fontWeight: 800, display: "inline-flex", alignItems: "center", justifyContent: "center", cursor: "pointer", userSelect: "none", marginLeft: 4 }}
      >i</span>
      {show && (
        <div style={{ position: "absolute", bottom: "calc(100% + 6px)", left: "50%", transform: "translateX(-50%)", background: C.dark, color: "#fff", fontSize: 11, lineHeight: 1.5, padding: "8px 12px", borderRadius: 8, width: 220, zIndex: 999, boxShadow: "0 4px 16px rgba(0,0,0,0.18)", pointerEvents: "none" }}>
          {text}
          <div style={{ position: "absolute", top: "100%", left: "50%", transform: "translateX(-50%)", borderWidth: 5, borderStyle: "solid", borderColor: `${C.dark} transparent transparent transparent` }} />
        </div>
      )}
    </span>
  );
}


// ── useSharedUserAssignmentData ─────────────────────────────────────────────
// Sprint 3, Task 13 — the one shared source of truth for a rep's own
// assignment/completion state. Before this hook, HomeScreen, QuizzesScreen's
// user branch, and LearnScreen each independently fetched
// getTenantAssignments/getUserQuizAttempts/getLessonCompletionsWithDates and
// ran their own copy of Task 12's realtime subscription — up to 3x the
// network calls and 3 separate channels all listening to the exact same
// table, with no guarantee the three screens agreed with each other at any
// given moment. Called once in App() and passed down as props; owns:
//   - assignments        — full tenant assignment list (dbToAssignment shape).
//                           Left unfiltered, same as every existing caller
//                           already did — each screen still filters to "mine"
//                           itself (HomeScreen/QuizzesScreen), or additionally
//                           to "everyone" for LearnScreen's manager tab, which
//                           needs the same underlying list, just unfiltered.
//   - lessonCompletionsAt — Map<lessonId, completedAt> for THIS user only.
//   - quizAttempts        — raw quiz_attempts rows for THIS user only.
//   - loading / error / retry — one composite retryable unit, same contract
//                           each screen's own loader already had.
//   - the ONE Task 12 realtime subscription for all three screens.
//   - applyLocalLessonCompletion / applyLocalQuizAttempt /
//     applyLocalAssignmentsCreated — optimistic local patches so a user's own
//     action (completing a lesson, submitting a quiz) or a manager's own
//     assignment creation still feels instant, without waiting for a
//     refetch/realtime round-trip.
//
// Deliberately NOT included: course/lesson catalog data (getTenantCourses /
// getTenantLessons). That's mutated by content-CRUD flows in LearnScreen's
// manager branch (create/edit/archive course & lesson) with ~10 separate
// call sites — pulling it into this layer would mean this hook also owning
// content-library management, which is a materially different concern from
// assignment/completion state and well outside "the smallest practical
// shared source of truth." HomeScreen and LearnScreen keep their own
// existing course/lesson fetches unchanged.
//
// `enabled` gates everything: only real, tenant-scoped rep sessions
// (isReal && tenantId && userId) fetch or subscribe. Demo/seed data and
// manager/admin sessions (who use separate tenant-wide tracking surfaces —
// see QuizTrackingPanel and LearnScreen's Assignments tab, both untouched by
// this task) never touch this hook's network calls.
function useSharedUserAssignmentData(tenantId, userId, enabled) {
  const active = enabled && !!tenantId && !!userId;
  const [assignments, setAssignments] = useState([]);
  const [lessonCompletionsAt, setLessonCompletionsAt] = useState(new Map());
  const [quizAttempts, setQuizAttempts] = useState([]);
  const [loading, setLoading] = useState(active);
  const [error, setError] = useState(null);
  // Bumped only on a successful assignments load (mirrors the old
  // "mark seen on every successful load" behavior HomeScreen depends on —
  // see its own effect that watches this to call updateLastSeenAssignmentsAt).
  const [loadedAt, setLoadedAt] = useState(null);

  const retry = useCallback(() => {
    if (!active) { setLoading(false); return; }
    setError(null);
    Promise.all([
      getTenantAssignments(tenantId),
      getLessonCompletionsWithDates(userId),
      // Answer confidentiality: learner list/status/history need only summaries.
      // getMyQuizAttemptsSafe returns the caller's own attempts WITHOUT the
      // answers JSON (legacy rows carry canonical `correct` there); raw
      // quiz_attempts rows never reach a learner's browser.
      getMyQuizAttemptsSafe(),
    ]).then(([{ data: a }, { data: done }, { data: attempts }]) => {
      if (a) { setAssignments(a); setLoadedAt(Date.now()); }
      if (done) setLessonCompletionsAt(done);
      if (attempts) setQuizAttempts(attempts);
      setError((!a || !done || !attempts) ? "Could not load your assignments. Please try again." : null);
      setLoading(false);
    }).catch(() => {
      setError("Could not load your assignments. Please try again.");
      setLoading(false);
    });
  }, [active, tenantId, userId]);

  useEffect(() => { retry(); }, [retry]);

  // Task 12 realtime — the ONE user-scoped tenant_assignments subscription
  // for Home + Quizzes + Learn combined (was 3 separate ones per screen).
  useEffect(() => {
    if (!active) return;
    return subscribeToTenantAssignments(tenantId, "user-shared", () => retry());
  }, [active, tenantId, retry]);

  const applyLocalLessonCompletion = useCallback((lessonId, completedAtIso) => {
    setLessonCompletionsAt(prev => new Map(prev).set(lessonId, completedAtIso));
  }, []);
  const applyLocalQuizAttempt = useCallback((attempt) => {
    setQuizAttempts(prev => [attempt, ...prev]);
  }, []);
  const applyLocalAssignmentsCreated = useCallback((rows) => {
    if (!rows?.length) return;
    setAssignments(prev => [...prev, ...rows]);
  }, []);
  // Assignment Experience Priority 1 — optimistic counterpart to
  // applyLocalAssignmentsCreated above, so Home/Learn/Quizzes drop a removed
  // assignment immediately instead of waiting on the ~400ms debounced
  // realtime refetch (subscribeToTenantAssignments above already covers the
  // case where the removal happened in a different tab/session).
  const applyLocalAssignmentsRemoved = useCallback((assignmentId) => {
    setAssignments(prev => prev.filter(a => a.id !== assignmentId));
  }, []);

  return {
    assignments, lessonCompletionsAt, quizAttempts,
    loading, error, loadedAt, retry,
    applyLocalLessonCompletion, applyLocalQuizAttempt, applyLocalAssignmentsCreated, applyLocalAssignmentsRemoved,
  };
}

function HomeScreen({ user, onNav, quizAssignments = [], onResumeLesson, onStartQuiz, onStartCourse, orgUsers = [], isReal = false, tenantId = null, quizzes = [], lastSeenAt = null, onNewAssignments = null, sharedAssignmentData = null, readinessThreshold = 80 }) {
  const mobile = useMobile();
  const firstName = user.name.split(" ")[0];
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";

  // Dynamic date: e.g. "Jun 28"
  const todayLabel = new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" });

  // Tasks panel visibility
  const [showTasksPanel, setShowTasksPanel] = useState(false);

  // ── Real-user assignment data ─────────────────────────────
  // Task 13 — assignments, lesson completions, and quiz attempts now come
  // from the shared hook (owned once in App(), see useSharedUserAssignmentData)
  // instead of HomeScreen fetching and subscribing to them itself. Only the
  // course/lesson catalog — a materially different, content-CRUD-owned
  // concern — stays as HomeScreen's own small fetch.
  const shared = sharedAssignmentData ?? {
    assignments: [], lessonCompletionsAt: new Map(), quizAttempts: [],
    loading: false, error: null, loadedAt: null, retry: () => {},
  };
  const homeAssignments  = shared.assignments;
  const homeCompletedAt  = shared.lessonCompletionsAt;
  const homeQuizAttempts = shared.quizAttempts;

  const [homeCourses,        setHomeCourses]        = useState([]);
  const [homeLessons,        setHomeLessons]        = useState([]);
  const [catalogLoading,     setCatalogLoading]     = useState(isReal);
  const [catalogError,       setCatalogError]       = useState(null);

  // ── Leaderboard sidebar — reads from user_point_events (single source of truth)
  const [homeLbRows, setHomeLbRows] = useState([]);
  useEffect(() => {
    if (!isReal || !tenantId) return;
    getLeaderboard(tenantId, user?.id).then(({ data }) => {
      if (data) setHomeLbRows(data.slice(0, 5));
    });
  }, [isReal, tenantId, user?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Course/lesson catalog — needed to render assignment cards (title,
  // lessonIds, etc.). Kept as its own small retryable fetch; combined with
  // the shared hook's loading/error below into one composite Home experience.
  const loadHomeCatalog = useCallback(() => {
    if (!isReal || !tenantId) { setCatalogLoading(false); return; }
    setCatalogError(null);
    Promise.all([
      getTenantCourses(tenantId),
      getTenantLessons(tenantId),
    ]).then(([{ data: c }, { data: l }]) => {
      if (c) setHomeCourses(c);
      if (l) setHomeLessons(l);
      setCatalogError((!c || !l) ? "Could not load your assignments. Please try again." : null);
      setCatalogLoading(false);
    }).catch(() => {
      setCatalogError("Could not load your assignments. Please try again.");
      setCatalogLoading(false);
    });
  }, [isReal, tenantId]);

  useEffect(() => { loadHomeCatalog(); }, [loadHomeCatalog]);

  // Composite loading/error — same retryable-unit contract Home always had;
  // now spans the catalog fetch plus the shared assignment data.
  const homeLoading = catalogLoading || shared.loading;
  const homeError   = catalogError ?? shared.error;
  const retryHome    = useCallback(() => { loadHomeCatalog(); shared.retry(); }, [loadHomeCatalog, shared.retry]); // eslint-disable-line react-hooks/exhaustive-deps

  // Mark assignments "seen" on every successful shared load (mount, retry, or
  // realtime-triggered refresh) — same rule as before Task 13: a failed
  // fetch (loadedAt unchanged) never updates last_seen_assignments_at, so
  // "NEW" badges persist until a load actually succeeds.
  useEffect(() => {
    if (!isReal || !user?.id || shared.loadedAt == null) return;
    updateLastSeenAssignmentsAt(user.id);
  }, [isReal, user?.id, shared.loadedAt]);

  // Report new-assignment count to App so the "Learn" nav badge stays in sync.
  // "new" = assigned after lastSeenAt (only meaningful when lastSeenAt is set).
  useEffect(() => {
    if (!isReal || !onNewAssignments || !lastSeenAt) { onNewAssignments?.(0); return; }
    const userTeamId = orgUsers.find(u => u.id === user?.id)?.teamId ?? null;
    const mine = homeAssignments.filter(a =>
      (a.assignedTo?.type === "group"      && a.assignedTo?.orgId === user?.orgId) ||
      (a.assignedTo?.type === "individual" && a.assignedTo?.userId === user?.id)   ||
      (a.assignedTo?.type === "team"       && userTeamId && userTeamId === a.assignedTo?.teamId)
    );
    const newCount = mine.filter(a => a.assignedAtRaw && a.assignedAtRaw > lastSeenAt).length;
    onNewAssignments(newCount);
  }, [homeAssignments, lastSeenAt]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Unified assignment enrichment ─────────────────────────
  // For real users: build enriched list from Supabase data.
  // For demo users: transform quizAssignments into the same shape.
  const enrichedAssignments = (() => {
    if (isReal) {
      const userTeamId = orgUsers.find(u => u.id === user?.id)?.teamId ?? null;
      const mine = homeAssignments.filter(a =>
        (a.assignedTo?.type === "group"      && a.assignedTo?.orgId === user?.orgId) ||
        (a.assignedTo?.type === "individual" && a.assignedTo?.userId === user?.id)   ||
        (a.assignedTo?.type === "team"       && userTeamId && userTeamId === a.assignedTo?.teamId)
      );
      // THE canonical current-work set (lessons + courses + quizzes), from the
      // one shared selector Learn also uses — so Home is a true preview of Learn.
      // One latest instance per content, cancelled excluded, resolved by the
      // shared engine. Missing content is dropped from the Home PREVIEW (it must
      // not render a clickable fake card); Learn surfaces it as a non-clickable
      // "unavailable" row.
      const rows = resolveLearnerAssignments(mine, {
        completedAtByLesson: homeCompletedAt,
        quizAttempts: homeQuizAttempts,
        courses: homeCourses, lessons: homeLessons, quizzes,
      });
      return rows.filter(r => !r.missing).map(r => {
        const a = r.assignment;
        const dueStatus = (!r.isCompleted && a.dueAt && a.dueAt !== "Open") ? getDueStatus(a.dueAt) : null;
        const isNew = !!lastSeenAt && !!a.assignedAtRaw && a.assignedAtRaw > lastSeenAt;
        return { ...a, content: r.content, contentKind: r.contentType, pct: r.progress, isComplete: r.isCompleted, dueStatus, isNew };
      });
    }
    // Demo: wrap quizAssignments (outstanding only shown, completed = has passed attempt)
    // + append the Continue Learning seed (in-progress course/lesson) — demo-only, unchanged quiz data.
    return [
      ...quizAssignments.map(q => {
        const isComplete = q.attempts?.some(a => a.passed) ?? false;
        const dueStatus = (q.dueAt && q.dueAt !== "Open") ? getDueStatus(q.dueAt) : null;
        return { ...q, content: q, contentKind: "quiz", pct: isComplete ? 100 : 0, isComplete, dueStatus, contentType: "quiz", contentId: q.id };
      }),
      ...DEMO_CONTINUE_LEARNING_SEED,
    ];
  })();

  const pendingAssignments   = enrichedAssignments.filter(x => !x.isComplete);
  const completedAssignments = enrichedAssignments.filter(x => x.isComplete);
  const overdueAssignments   = pendingAssignments.filter(x => x.dueStatus?.label === "Overdue");
  const pendingCount         = pendingAssignments.length;

  // For demo backwards-compat: recommended quiz
  const outstanding    = quizAssignments.filter(q => !q.attempts?.some(a => a.passed));
  const recommendedQuiz = !isReal ? (outstanding.find(q => !q.attempts?.length) ?? null) : null;

  return (
    <PersonalDashboardScreen
      user={user}
      onNav={onNav}
      isReal={isReal}
      tenantId={tenantId}
      orgUsers={orgUsers}
      enrichedAssignments={enrichedAssignments}
      pendingAssignments={pendingAssignments}
      completedAssignments={completedAssignments}
      overdueAssignments={overdueAssignments}
      homeLoading={homeLoading}
      homeError={homeError}
      onRetryHome={retryHome}
      onResumeLesson={onResumeLesson}
      onStartCourse={onStartCourse}
      onStartQuiz={onStartQuiz}
      homeLbRows={homeLbRows}
      quizzes={quizzes}
      quizAssignments={quizAssignments}
      homeCourses={homeCourses}
      homeLessons={homeLessons}
      homeQuizAttempts={homeQuizAttempts}
      readinessThreshold={readinessThreshold}
    />
  );
}

// ── PersonalDashboardScreen ─────────────────────────────────────────────────
// Individual contributor home view. Uses the Leadership Dashboard design
// language, scoped entirely to the current user's own data.
// Managers/admins are routed to LeadershipDashboardScreen via case "home".
function PersonalDashboardScreen({
  user, onNav, isReal, tenantId, orgUsers,
  enrichedAssignments, pendingAssignments, completedAssignments, overdueAssignments,
  homeLoading, homeError, onRetryHome, onResumeLesson, onStartCourse, onStartQuiz, homeLbRows, quizzes,
  quizAssignments = [], homeCourses = [], homeLessons = [], homeQuizAttempts = [],
  readinessThreshold = 80,
}) {
  const mobile     = useMobile();
  // Home "Assigned Learning" is a preview of the SAME unified current-work set
  // Learn shows — lessons, courses AND quizzes — from the shared selector
  // (enrichedAssignments in HomeScreen). Quiz assignments still route into the
  // canonical Quizzes flow on click; Home never re-implements grading/attempts.
  const learningPending   = pendingAssignments;
  const learningCompleted = completedAssignments;
  const firstName  = (user.name ?? "").split(" ")[0];
  const hour       = new Date().getHours();
  const greeting   = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
  const todayLabel = new Date().toLocaleDateString("en-US", { month: "short", day: "numeric" });

  // ── Fetch personal performance, topic scores, and recent activity ──────────
  const [perf,           setPerf]           = useState(null);
  const [recs,           setRecs]           = useState([]);
  const [topicScores,    setTopicScores]    = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  // Full quiz_attempts rows (incl. answers, for review) — fetched once by the parent
  // HomeScreen (it also needs them to determine Assigned Learning completion) and
  // passed down here as `homeQuizAttempts`, so this list and the assignment-completion
  // check can never fall out of sync with each other.
  const quizAttemptsFull = homeQuizAttempts;
  const [perfLoading,    setPerfLoading]    = useState(isReal);
  // Recent Activity / Recent Quizzes → quiz review modal. null when closed.
  const [activityReview, setActivityReview] = useState(null); // { quiz, attempt } | null

  useEffect(() => {
    if (!isReal || !tenantId || !user?.id) { setPerfLoading(false); return; }
    Promise.all([
      // Own performance/topics → learner-safe RPC source (survives migration 057).
      getUserPerformance(tenantId, user.id, { safe: true }),
      getRepTopicScores(tenantId, user.id, { safe: true }),
      supabase
        .from("user_point_events")
        // Task 18 — quiz_attempt_id (added 041_quiz_attempt_id_on_point_events.sql)
        // lets findAttemptForEvent() open the exact attempt an event was
        // earned from, instead of guessing via nearest timestamp. NULL for
        // lesson/course/game rows and for quiz rows written before that
        // migration — those still fall back to the old timestamp match.
        .select("source_type, source_id, points, created_at, quiz_attempt_id")
        .eq("tenant_id", tenantId)
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(8),
    ]).then(([perfResult, topics, { data: events }]) => {
      if (perfResult?.data) {
        setPerf(perfResult.data);
        setRecs(getRecommendations(perfResult.data));
      }
      if (Array.isArray(topics) && topics.length) setTopicScores(topics);
      if (events) setRecentActivity(events);
      setPerfLoading(false);
    }).catch(() => setPerfLoading(false));
  }, [isReal, tenantId, user?.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Derived values ─────────────────────────────────────────────────────────
  const readinessScore = isReal ? (perf?.score ?? null)             : (user.score ?? null);
  // Knowledge Score = raw quiz accuracy (distinct from the weighted Overall Readiness score).
  const knowledgeScore = isReal
    ? (perf?.quizzesAttempted > 0 ? perf.avgQuizScore : null)
    : (() => {
        const scored = quizAssignments.flatMap(q => q.attempts?.map(a => a.score) ?? []).filter(s => s != null);
        return scored.length ? Math.round(scored.reduce((s, v) => s + v, 0) / scored.length) : null;
      })();
  const currentStreak  = user.streak ?? 0;
  const weeklyXp = isReal
    ? (() => {
        const since = Date.now() - 7 * 86_400_000;
        return recentActivity
          .filter(e => new Date(e.created_at).getTime() > since)
          .reduce((s, e) => s + (e.points ?? 0), 0);
      })()
    : Math.round((user.xp ?? 0) * 0.15);
  const teamRank     = user.rank ?? null;
  const totalMembers = orgUsers.length > 0 ? orgUsers.length : null;

  // ── Design helpers — same tokens as LeadershipDashboard ───────────────────
  const scoreColor = (s) => s >= 85 ? C.trueGreen : s >= 70 ? C.orange : C.red;
  const scoreBg    = (s) => s >= 85 ? C.trueGreenBg : s >= 70 ? C.orangeLight : C.redBg;

  const ScoreBadge = ({ score, size = 14 }) => score != null ? (
    <span style={{ fontSize: size, fontWeight: 800, color: scoreColor(score),
      background: scoreBg(score), padding: "2px 8px", borderRadius: 6 }}>
      {score}%
    </span>
  ) : null;

  const SH = (title, sub) => (
    <div style={{ marginBottom: 14 }}>
      <div style={{ fontSize: 15, fontWeight: 800, color: C.text }}>{title}</div>
      {sub && <div style={{ fontSize: 12, color: C.textSub, marginTop: 2 }}>{sub}</div>}
    </div>
  );

  // ── Demo quiz results from quizAssignments (same source as old HomeScreen) ──
  const demoQuizResults = !isReal
    ? quizAssignments.filter(q => q.attempts?.length).slice(0, 4).map(q => {
        const attempt = q.attempts[0];
        return {
          name:        q.title ?? q.name ?? "Quiz",
          date:        q.dueAt && q.dueAt !== "Open" ? q.dueAt : "",
          score:       attempt?.score ?? null,
          passed:      q.attempts?.some(a => a.passed) ?? false,
          attemptNum:  q.attempts.length > 1 ? q.attempts.length : null,
          clickable:   !!attempt,
          quiz: q, attempt,
        };
      })
    : [];

  // Real: built directly from quizAttemptsFull (the same fetch that also drives
  // Assigned Learning completion above) — already ordered newest-first, and not
  // limited to a rolling 30-day scoring window like perf.recentQuizAttempts was,
  // so this always reflects the true latest attempts, not a scoring-derived subset.
  const realQuizResults = isReal
    ? quizAttemptsFull.slice(0, 4).map(a => {
        const q = quizzes?.find(qz => qz.id === a.quiz_id);
        return {
          name:        q?.title ?? q?.name ?? "Quiz",
          date:        a.created_at ? new Date(a.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "",
          score:       a.score,
          passed:      a.passed,
          attemptNum:  a.attempt_num ?? null,
          clickable:   !!q,
          quiz: q, attempt: a,
        };
      })
    : [];

  // Shared with Recent Activity's click-through — opens the exact same
  // QuizResultsView-based review modal, so there's one review experience, not two.
  const openAttemptReview = (quiz, rawAttempt) => {
    if (!quiz || !rawAttempt) return;
    if (!isReal) {
      // Demo — canonical seed quiz, rendered by QuizResultsView as before.
      setActivityReview({ mode: "demo", quiz, attempt: rawAttempt });
      return;
    }
    // Real learner — answer key is pass-gated and comes ONLY from the immutable
    // snapshot via get_quiz_review. The SANITIZED current questions (no answer
    // keys) are fetched only to LABEL a trusted attempt's rows so a failed
    // review shows the real prompt; legacy attempts get no labels and degrade
    // honestly. The learner's browser never receives canonical answer keys here.
    const quizName = quiz.name ?? quiz.title ?? "Quiz";
    const fmt = (iso) => { try { return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); } catch { return ""; } };
    setActivityReview({ mode: "loading", quizName });
    Promise.allSettled([getQuizReview(quiz.id), getQuizForAttempt(quiz.id)])
      .then(([revRes, quizRes]) => {
        const review = revRes.status === "fulfilled" ? revRes.value : { data: null, error: revRes.reason };
        if (review.error || !review.data) { setActivityReview({ mode: "error", quizName, quizId: quiz.id }); return; }
        const sanitized = (quizRes.status === "fulfilled" && !quizRes.value.error && quizRes.value.data)
          ? (rpcQuizToTakeable(quizRes.value.data)?.questions ?? null) : null;
        const m = buildLearnerReviewModel({ reviewData: review.data, attemptId: rawAttempt.id, sanitizedQuestions: sanitized });
        if (!m) { setActivityReview({ mode: "error", quizName, quizId: quiz.id }); return; }
        setActivityReview({
          mode: "real", quizName, quizId: quiz.id,
          model: {
            attempt:     { score: m.score, passed: m.passed, date: fmt(m.createdAt) },
            rows:        m.rows,
            reveal:      m.reveal,
            unavailable: m.unavailable,
          },
        });
      })
      .catch(() => setActivityReview({ mode: "error", quizName, quizId: quiz.id }));
  };

  // ── Demo topic scores derived from USER_GAME_HISTORY answers ──────────────
  const demoTopicScores = (() => {
    if (isReal) return [];
    const map = {};
    USER_GAME_HISTORY.forEach(g => {
      (g.questions ?? []).forEach(q => {
        if (!map[q.topic]) map[q.topic] = { correct: 0, total: 0 };
        map[q.topic].total++;
        if (q.isCorrect) map[q.topic].correct++;
      });
    });
    return Object.entries(map)
      .map(([topic, { correct, total }]) => ({ topic, avgScore: Math.round((correct / total) * 100) }))
      .sort((a, b) => b.avgScore - a.avgScore);
  })();

  const displayTopicScores = isReal ? topicScores : demoTopicScores;

  // ── Demo recommendations ───────────────────────────────────────────────────
  const demoRecs = !isReal ? [
    { priority: "high",   type: "quiz",    action: "Retake Pipeline Management quiz",   reason: "You missed 3 questions — a retake adds +6 pts to your readiness score." },
    { priority: "medium", type: "lesson",  action: "Finish Competitive Positioning",    reason: "Incomplete modules reduce your learning score." },
    { priority: "low",    type: "game",    action: "Join the next live Ralli session",  reason: "Live game participation accounts for 25% of your readiness." },
  ] : [];

  const displayRecs        = isReal ? recs : demoRecs;
  const recColorMap        = { high: C.red, medium: C.orange, low: C.blue };
  const recTypeIcon        = { quiz: "📝", lesson: "📖", course: "🎓", game: "⚡", engagement: "🔄" };

  // ── Demo recent activity ───────────────────────────────────────────────────
  // Linked to real demo content (existing quiz/lesson/course records — no invented history):
  //   quiz   → qa5 "Discovery Call Framework" (has a seeded attempt with full answers)
  //   lesson → ll4 "Handling the 'Not Interested' Objection"
  //   course → lc1 "Objection Handling Mastery"
  const demoActivity = !isReal ? [
    { source_type: "quiz",   source_id: "qa5", points: 150, created_at: new Date(Date.now() - 2 * 3_600_000).toISOString() },
    { source_type: "lesson", source_id: "ll4", points: 75,  created_at: new Date(Date.now() - 26 * 3_600_000).toISOString() },
    { source_type: "game",   points: 200, created_at: new Date(Date.now() - 2 * 86_400_000).toISOString() },
    { source_type: "course", source_id: "lc1", points: 100, created_at: new Date(Date.now() - 3 * 86_400_000).toISOString() },
  ] : [];

  const displayActivity = isReal ? recentActivity : demoActivity;

  const activityBg = (type) =>
    ({ lesson: "#DBEAFE", quiz: C.purple + "18", game: C.orangeLight, course: C.trueGreenBg })[type] ?? C.pageBg;
  const activityTime = (iso) => {
    const diff = Date.now() - new Date(iso).getTime();
    if (diff < 3_600_000)       return `${Math.round(diff / 60_000)}m ago`;
    if (diff < 86_400_000)      return `${Math.round(diff / 3_600_000)}h ago`;
    if (diff < 2 * 86_400_000)  return "Yesterday";
    return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric" });
  };

  // ── Resolve a Recent Activity row → display title + click target ───────────
  // Reuses already-fetched content (quizzes / homeCourses / homeLessons for real
  // accounts; the existing demo content seeds for demo accounts). No new fetches,
  // no new content records — only a lookup by the event's source_id.
  const resolveActivityContent = (e) => {
    const id = e.source_id;
    // "attempted" distinguishes "this is a lesson/quiz/course whose content we tried to
    // resolve" (missing → safe fallback note) from types like game/bonus that never had
    // linkable content to begin with.
    if (!id) return { kind: e.source_type, title: null, clickable: false, attempted: false };
    if (e.source_type === "quiz") {
      const quiz = isReal ? quizzes?.find(q => q.id === id) : quizAssignments.find(q => q.id === id);
      const title = quiz?.title ?? quiz?.name ?? null;
      return { kind: "quiz", title, clickable: !!title, quiz, attempted: true };
    }
    if (e.source_type === "lesson") {
      const lesson = isReal ? homeLessons.find(l => l.id === id) : INITIAL_LEARN_LESSONS.find(l => l.id === id);
      return { kind: "lesson", title: lesson?.title ?? null, clickable: !!lesson, lesson, attempted: true };
    }
    if (e.source_type === "course") {
      const course = isReal ? homeCourses.find(c => c.id === id) : INITIAL_LEARN_COURSES.find(c => c.id === id);
      return { kind: "course", title: course?.title ?? null, clickable: !!course, course, attempted: true };
    }
    return { kind: e.source_type, title: null, clickable: false, attempted: false };
  };

  const activityLabel = (e) => {
    const { kind, title } = resolveActivityContent(e);
    if (title) return `Completed: ${title}`;
    return ({ lesson: "Completed lesson", quiz: "Completed quiz", game: "Played live game", course: "Completed course" })[kind]
      ?? "Activity";
  };

  // Find the specific quiz attempt (with per-question answers) tied to a point event,
  // so the review modal opens the exact prior attempt rather than just "the latest".
  //
  // Task 18 — events written by submit_quiz_attempt_atomic() (since
  // 041_quiz_attempt_id_on_point_events.sql) carry a stable quiz_attempt_id,
  // so we match on that exact id first: no ambiguity from rapid retakes,
  // multiple tabs, or timestamp precision. Older events written before that
  // migration have quiz_attempt_id = NULL and fall back to the original
  // nearest-created_at heuristic — kept only for that legacy case.
  const findAttemptForEvent = (e, quiz) => {
    if (isReal) {
      let raw = null;
      if (e.quiz_attempt_id) {
        raw = quizAttemptsFull.find(a => a.id === e.quiz_attempt_id) ?? null;
      }
      if (!raw) {
        // Legacy fallback — pre-Task-18 events only.
        const candidates = quizAttemptsFull.filter(a => a.quiz_id === e.source_id);
        if (candidates.length) {
          const targetMs = new Date(e.created_at).getTime();
          const closest = candidates.reduce((best, a) => {
            const diff = Math.abs(new Date(a.created_at).getTime() - targetMs);
            return (!best || diff < best.diff) ? { attempt: a, diff } : best;
          }, null);
          raw = closest?.attempt ?? null;
        }
      }
      if (!raw) return null;
      return {
        id:      raw.id,           // needed to match the exact attempt in get_quiz_review
        created_at: raw.created_at,
        score:   raw.score,
        passed:  raw.passed,
        answers: raw.answers ?? [],
        date:    new Date(raw.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }),
      };
    }
    // Demo: reuse the quiz's own seeded attempt — no invented history.
    return quiz?.attempts?.[0] ?? null;
  };

  const handleActivityClick = (e) => {
    const info = resolveActivityContent(e);
    if (!info.clickable) return;
    if (info.kind === "quiz") {
      const attempt = findAttemptForEvent(e, info.quiz);
      if (!attempt) return; // no matching attempt on record — safe no-op fallback
      openAttemptReview(info.quiz, attempt);
    } else if (info.kind === "lesson") {
      onResumeLesson?.(info.lesson.id);
    } else if (info.kind === "course") {
      onStartCourse?.(info.course.id);
    }
  };

  // ── Loading state ──────────────────────────────────────────────────────────
  if ((homeLoading || perfLoading) && isReal) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>My Dashboard</h2>
          <p style={{ margin: "4px 0 0", fontSize: 13, color: C.textSub }}>Loading your readiness data…</p>
        </div>
        <LoadingState rows={5} message="Fetching performance data…" />
      </div>
    );
  }

  // Task 8 — a failed assignment fetch used to leave the dashboard showing
  // stale/empty data with no indication anything went wrong. perf-fetch
  // errors are out of scope here (separate, non-assignment data).
  if (homeError && isReal) {
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>My Dashboard</h2>
        </div>
        <ErrorState message={homeError} onRetry={onRetryHome} />
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>

      {/* ── Header ─────────────────────────────────────────── */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
        <div>
          {currentStreak > 0 && (
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 4 }}>
              <span style={{ fontSize: 13, fontWeight: 600, color: C.orange }}>{currentStreak}-day streak</span>
              <span style={{ fontSize: 13, color: C.textSub }}>· Keep it going</span>
            </div>
          )}
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>{greeting}, {firstName}</h2>
          <p style={{ margin: "4px 0 0", fontSize: 13, color: C.textSub }}>
            {todayLabel} · Personal Readiness
          </p>
        </div>
        {readinessScore != null && <ScoreBadge score={readinessScore} size={16} />}
      </div>

      {/* ── TOP — 5 KPI cards ──────────────────────────────── */}
      <div style={{ display: "grid", gridTemplateColumns: mobile ? "repeat(2, 1fr)" : "repeat(5, 1fr)", gap: 14 }}>
        {[
          {
            label: "Overall Readiness",
            value: readinessScore != null ? `${readinessScore}%` : "—",
            sub:   readinessScore != null ? "Last 30 days" : "Complete activities to unlock",
            color: readinessScore != null ? scoreColor(readinessScore) : C.textMuted,
            tooltip: "Weighted average of your quiz accuracy, lesson completion, and game performance over the past 30 days.",
          },
          {
            label: "Knowledge Score",
            value: knowledgeScore != null ? `${knowledgeScore}%` : "—",
            sub:   knowledgeScore != null ? "Avg. quiz accuracy" : "Take a quiz to unlock",
            color: knowledgeScore != null ? scoreColor(knowledgeScore) : C.textMuted,
            tooltip: "Your average score across all quiz attempts.",
          },
          {
            label: "Team Rank",
            value: teamRank != null ? `#${teamRank}` : "—",
            sub:   totalMembers ? `of ${totalMembers} members` : "No rankings yet",
            color: teamRank != null && teamRank <= 3 ? C.trueGreen : C.text,
          },
          {
            label: "Weekly XP",
            value: weeklyXp > 0 ? weeklyXp.toLocaleString() : "—",
            sub:   weeklyXp > 0 ? "This week" : "No activity this week",
            color: weeklyXp > 0 ? C.orange : C.textMuted,
          },
          {
            label: "Current Streak",
            value: currentStreak > 0 ? `${currentStreak}` : "—",
            sub:   currentStreak > 0 ? `day${currentStreak !== 1 ? "s" : ""} in a row` : "Start an activity",
            color: currentStreak >= 7 ? C.trueGreen : currentStreak > 0 ? C.orange : C.textMuted,
          },
        ].map((s, i) => (
          <Card key={i}>
            <div style={{ fontSize: 26, fontWeight: 900, color: s.color }}>{s.value}</div>
            <div style={{ fontSize: 12, fontWeight: 700, color: C.text, marginTop: 4, display: "flex", alignItems: "center", gap: 4 }}>
              {s.label}
              {s.tooltip && <InfoTooltip text={s.tooltip} />}
            </div>
            <div style={{ fontSize: 11, color: C.textSub, marginTop: 2 }}>{s.sub}</div>
          </Card>
        ))}
      </div>

      {/* ── Continue Learning — in-progress assignments, resume where you left off ── */}
      {(() => {
        // In-progress items from the unified current-work set (lessons/courses/
        // quizzes). A quiz card routes into the canonical Quizzes flow on click.
        const inProgress = learningPending.filter(x => x.pct > 0);
        if (!inProgress.length) return null;
        return (
          <div>
            {SH("Continue Learning", "Pick up where you left off")}
            <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr" : `repeat(${Math.min(inProgress.length, 3)}, 1fr)`, gap: 14 }}>
              {inProgress.slice(0, 3).map((item) => {
                const { content, contentKind, pct } = item;
                const typeColor = contentKind === "course" ? (content.color ?? C.orange)
                  : contentKind === "quiz" ? C.purple : LESSON_TYPE_COLORS[content.type] ?? C.blue;
                const handleAction = () => {
                  if (contentKind === "quiz")        onStartQuiz?.(content.id);
                  else if (contentKind === "course") onStartCourse?.(content.id);
                  else                               onResumeLesson?.(content.id);
                };
                return (
                  <Card key={item.id}>
                    <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 8 }}>{content.title ?? content.name}</div>
                    <ProgressBar value={pct} color={typeColor} height={6} />
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 10 }}>
                      <span style={{ fontSize: 11, color: C.textSub }}>{pct}% complete</span>
                      <button onClick={handleAction}
                        style={{ padding: "6px 12px", borderRadius: 7, border: "none", cursor: "pointer",
                          background: typeColor, color: "#fff", fontSize: 12, fontWeight: 700 }}>
                        Resume →
                      </button>
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
        );
      })()}

      {/* ── MIDDLE — Assigned Learning + Quiz Results + Leaderboard ─────────── */}
      <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr" : "1fr 300px", gap: 16 }}>

        {/* Left — Assigned + In Progress ─────────────── */}
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {SH("Assigned Learning",
            learningPending.length > 0
              ? `${learningPending.length} pending · ${learningCompleted.length} complete`
              : "All caught up"
          )}

          {homeLoading ? (
            <Card><p style={{ margin: 0, fontSize: 14, color: C.textSub }}>Loading assignments…</p></Card>
          ) : learningPending.length === 0 ? (
            <Card>
              <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 8 }}>
                <div style={{ width: 8, height: 8, borderRadius: 2, background: C.trueGreen }} />
                <span style={{ fontSize: 11, fontWeight: 700, color: C.trueGreen, letterSpacing: "0.06em" }}>ALL CAUGHT UP</span>
              </div>
              <p style={{ margin: 0, fontSize: 14, color: C.textSub }}>
                No outstanding assignments. Check the Learn or Quizzes tabs for more content.
              </p>
            </Card>
          ) : learningPending.slice(0, 3).map((item) => {
            const { content, contentKind, pct, dueStatus } = item;
            const typeColor = contentKind === "course" ? (content.color ?? C.orange)
              : contentKind === "quiz" ? C.purple : LESSON_TYPE_COLORS[content.type] ?? C.blue;
            const typeLabel = contentKind === "course" ? "COURSE" : contentKind === "quiz" ? "QUIZ" : "LESSON";
            const handleAction = () => {
              if (contentKind === "quiz")        onStartQuiz?.(content.id);
              else if (contentKind === "course") onStartCourse?.(content.id);
              else                               onResumeLesson?.(content.id);
            };
            return (
              <Card key={item.id}>
                <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 10 }}>
                  <div style={{ width: 8, height: 8, borderRadius: 2, background: typeColor }} />
                  <span style={{ fontSize: 11, fontWeight: 700, color: typeColor, letterSpacing: "0.06em" }}>{typeLabel}</span>
                  {/* Assignment Experience Priority 5 — always show one of
                      Required/Recommended, never omit the badge. Neutral gray
                      for Recommended so it never looks like the blue "NEW"
                      badge next to it. */}
                  <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 4, background: item.required ? C.redBg : "#F1F5F9", color: item.required ? C.red : "#475569" }}>{item.required ? "REQUIRED" : "RECOMMENDED"}</span>
                  {item.isNew    && <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 6px", borderRadius: 4, background: "#DBEAFE", color: "#2563EB" }}>NEW</span>}
                  {dueStatus && (
                    <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 7px", borderRadius: 4,
                      background: dueStatus.color + "18", color: dueStatus.color, marginLeft: "auto" }}>
                      {dueStatus.label}
                    </span>
                  )}
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 12 }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: C.text }}>{content.title ?? content.name}</div>
                    <div style={{ display: "flex", gap: 10, marginTop: 4, fontSize: 12, color: C.textSub }}>
                      {contentKind === "course" && <span>{(content.lessonIds ?? []).length} lessons</span>}
                      {contentKind === "lesson" && content.duration && <span>⏱ {content.duration}</span>}
                      {contentKind === "quiz"   && <span>{questionCountOf(content)} questions</span>}
                      {(content.xp || content.xp === 0) && <span style={{ color: C.orange, fontWeight: 600 }}>+{content.xp} XP</span>}
                      {item.dueAt && item.dueAt !== "Open" && <span>Due {item.dueAt}</span>}
                    </div>
                  </div>
                  {pct > 0 && (
                    <div style={{ textAlign: "right", flexShrink: 0 }}>
                      <div style={{ fontSize: 18, fontWeight: 800, color: typeColor }}>{pct}%</div>
                      <div style={{ fontSize: 10, color: C.textSub }}>complete</div>
                    </div>
                  )}
                </div>
                {pct > 0 && (
                  <div style={{ marginTop: 10, marginBottom: 10 }}>
                    <ProgressBar value={pct} color={typeColor} height={5} />
                  </div>
                )}
                <div style={{ marginTop: pct > 0 ? 0 : 12 }}>
                  <button onClick={handleAction}
                    style={{ padding: "8px 16px", borderRadius: 8, border: "none", cursor: "pointer",
                      background: typeColor, color: "#fff", fontSize: 13, fontWeight: 700 }}>
                    {pct > 0 ? "Resume →" : "Start →"}
                  </button>
                </div>
              </Card>
            );
          })}

          {learningPending.length > 3 && (
            <button
              onClick={() => onNav?.("learn")}
              style={{ padding: "10px", borderRadius: 10, border: `1px solid ${C.border}`,
                background: C.pageBg, color: C.orange, fontSize: 13, fontWeight: 600,
                cursor: "pointer", textAlign: "center" }}
            >
              +{learningPending.length - 3} more — View all in Learn →
            </button>
          )}
        </div>

        {/* Right — Recent Quiz Results + Mini Leaderboard ─ */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>

          {/* Recent Quizzes */}
          <div>
            {SH("Recent Quizzes", "")}
            <Card style={{ padding: 0, overflow: "hidden" }}>
              {(isReal ? realQuizResults : demoQuizResults).length === 0 ? (
                <div style={{ padding: "24px 20px", textAlign: "center" }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 4 }}>No quizzes yet</div>
                  <div style={{ fontSize: 12, color: C.textSub, marginBottom: 12 }}>
                    Your results will appear here after your first attempt.
                  </div>
                  <button
                    onClick={() => onNav?.("learn")}
                    style={{ padding: "7px 14px", borderRadius: 8, border: `1px solid ${C.orangeBorder}`,
                      background: C.orangeLight, color: C.orange, fontSize: 12, fontWeight: 600, cursor: "pointer" }}
                  >
                    Go to Learn →
                  </button>
                </div>
              ) : (isReal ? realQuizResults : demoQuizResults).map((q, i, arr) => (
                <div
                  key={i}
                  onClick={q.clickable ? () => openAttemptReview(q.quiz, q.attempt) : undefined}
                  style={{ padding: "13px 18px", borderBottom: i < arr.length - 1 ? `1px solid ${C.border}` : "none",
                    display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12,
                    cursor: q.clickable ? "pointer" : "default" }}
                >
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: q.clickable ? C.orange : C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{q.name}</div>
                    <div style={{ fontSize: 11, color: C.textSub, marginTop: 2 }}>
                      {q.date}{q.attemptNum ? ` · Attempt ${q.attemptNum}` : ""}{q.rank != null ? ` · Rank #${q.rank}` : ""}
                    </div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
                    <div style={{ textAlign: "right" }}>
                      <div style={{ fontSize: 14, fontWeight: 800, color: scoreColor(q.score) }}>{q.score}%</div>
                      {q.passed != null && (
                        <div style={{ fontSize: 10, fontWeight: 600, color: q.passed ? C.trueGreen : C.red }}>
                          {q.passed ? "Passed" : "Failed"}
                        </div>
                      )}
                    </div>
                    {q.clickable && <span style={{ fontSize: 12, color: C.textMuted }}>›</span>}
                  </div>
                </div>
              ))}
            </Card>
          </div>

          {/* Mini Leaderboard */}
          <div>
            {SH("Team Leaderboard", "")}
            <Card style={{ padding: 0, overflow: "hidden" }}>
              {(() => {
                const lbData = isReal
                  ? homeLbRows.map(r => ({ ...r, score: r.total }))
                  : leaderboardData.slice(0, 5).map(p => ({ ...p, isMe: p.userId ? p.userId === user?.id : !!p.isMe }));
                if (!lbData.length) {
                  return (
                    <div style={{ padding: "20px", textAlign: "center", fontSize: 12, color: C.textSub }}>
                      Rankings appear once your team earns XP.
                    </div>
                  );
                }
                return (
                  <>
                    {lbData.map((p, i) => (
                      <div
                        key={p.userId ?? i}
                        style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 16px",
                          background: p.isMe ? C.orangeLight : "transparent",
                          borderBottom: i < lbData.length - 1 ? `1px solid ${C.border}` : "none" }}
                      >
                        <div style={{ width: 20, height: 20, borderRadius: "50%",
                          background: p.rank === 1 ? "#F5A623" : p.rank === 2 ? "#A8B2C0" : p.rank === 3 ? "#CD7F32" : C.pageBg,
                          display: "flex", alignItems: "center", justifyContent: "center",
                          fontSize: 10, fontWeight: 800, color: p.rank <= 3 ? "#fff" : C.textSub, flexShrink: 0 }}>
                          {p.rank}
                        </div>
                        <Avatar initials={p.initials} size={26} color={p.color} />
                        <div style={{ flex: 1, minWidth: 0, fontSize: 12, fontWeight: p.isMe ? 700 : 500,
                          color: p.isMe ? C.orange : C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                          {p.name}
                        </div>
                        <div style={{ fontSize: 12, fontWeight: 700, color: C.text, flexShrink: 0 }}>
                          {(p.score ?? 0).toLocaleString()}
                        </div>
                      </div>
                    ))}
                    <div style={{ padding: "10px 16px", borderTop: `1px solid ${C.border}`, textAlign: "center" }}>
                      <span onClick={() => onNav?.("leaderboard")}
                        style={{ fontSize: 12, color: C.orange, fontWeight: 600, cursor: "pointer" }}>
                        Full leaderboard →
                      </span>
                    </div>
                  </>
                );
              })()}
            </Card>
          </div>
        </div>
      </div>

      {/* ── BOTTOM — Topic Heatmap + Recommendations ────────── */}
      <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr" : "1fr 1fr", gap: 16 }}>

        {/* Personal Topic Heatmap */}
        <Card>
          {SH("Knowledge by Topic", "Based on your verified quiz attempts")}
          {displayTopicScores.length === 0 ? (
            <div style={{ padding: "20px 0", textAlign: "center", color: C.textSub, fontSize: 13 }}>
              Complete tagged quizzes to see your topic-by-topic breakdown.
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {[...displayTopicScores].sort((a, b) => b.avgScore - a.avgScore).map(t => {
                const s = t.avgScore ?? 0;
                const barColor = s >= 85 ? C.trueGreen : s >= readinessThreshold ? C.orange : C.red;
                return (
                  <div key={t.tagId ?? t.topic}>
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
                      <span style={{ fontSize: 12, fontWeight: 600, color: C.text, textTransform: "capitalize" }}>{t.topic}</span>
                      <span style={{ fontSize: 12, fontWeight: 800, color: barColor }}>{s}%</span>
                    </div>
                    <ProgressBar value={s} color={barColor} height={7} />
                  </div>
                );
              })}
              <div style={{ display: "flex", gap: 12, marginTop: 4 }}>
                {[{ label: "Strong ≥85", color: C.trueGreen }, { label: `On Track ≥${readinessThreshold}`, color: C.orange }, { label: `At Risk <${readinessThreshold}`, color: C.red }]
                  .map(({ label, color }) => (
                    <div key={label} style={{ display: "flex", alignItems: "center", gap: 4 }}>
                      <div style={{ width: 8, height: 8, borderRadius: 2, background: color }} />
                      <span style={{ fontSize: 10, color: C.textMuted }}>{label}</span>
                    </div>
                  ))}
              </div>
            </div>
          )}
        </Card>

        {/* Recommended Next Actions */}
        <Card>
          {SH("Recommended Next Actions", "Personalized to close your performance gaps")}
          {displayRecs.length === 0 ? (
            <div style={{ padding: "20px 0", textAlign: "center", color: C.textSub, fontSize: 13 }}>
              {isReal ? "No recommendations yet — keep completing activities." : "All caught up!"}
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {displayRecs.map((rec, i) => {
                const color = recColorMap[rec.priority] ?? C.textSub;
                return (
                  <div key={i} style={{ display: "flex", gap: 12, padding: "12px 14px",
                    borderRadius: C.radiusSm, background: color + "0d", border: `1px solid ${color}22` }}>
                    <div style={{ fontSize: 16, flexShrink: 0, lineHeight: 1.4 }}>
                      {recTypeIcon[rec.type] ?? "•"}
                    </div>
                    <div>
                      <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 3 }}>{rec.action}</div>
                      <div style={{ fontSize: 12, color: C.textSub, lineHeight: 1.5 }}>{rec.reason}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      </div>

      {/* ── Recent Activity ─────────────────────────────────── */}
      <Card>
        {SH("Recent Activity", "Your latest XP-earning events")}
        {displayActivity.length === 0 ? (
          <div style={{ padding: "20px 0", textAlign: "center", color: C.textSub, fontSize: 13 }}>
            No activity yet. Complete a lesson, quiz, or game to earn XP.
          </div>
        ) : (
          <div>
            {displayActivity.map((e, i) => {
              const info = resolveActivityContent(e);
              const clickable = info.clickable;
              return (
                <div
                  key={i}
                  onClick={clickable ? () => handleActivityClick(e) : undefined}
                  style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 0",
                    borderBottom: i < displayActivity.length - 1 ? `1px solid ${C.border}` : "none",
                    cursor: clickable ? "pointer" : "default",
                    borderRadius: clickable ? 8 : 0 }}
                >
                  <div style={{ width: 34, height: 34, borderRadius: 8, background: activityBg(e.source_type),
                    display: "flex", alignItems: "center", justifyContent: "center", fontSize: 15, flexShrink: 0 }}>
                    {recTypeIcon[e.source_type] ?? "⚡"}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: clickable ? C.orange : C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {activityLabel(e)}
                    </div>
                    <div style={{ fontSize: 11, color: C.textSub }}>
                      {activityTime(e.created_at)}
                      {info.attempted && !info.title ? " · content unavailable" : ""}
                    </div>
                  </div>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.orange, flexShrink: 0 }}>+{e.points} XP</div>
                  {clickable && <span style={{ fontSize: 12, color: C.textMuted, flexShrink: 0 }}>›</span>}
                </div>
              );
            })}
          </div>
        )}
      </Card>

      {/* ── Recent Activity: quiz review modal ──
          Demo → canonical QuizResultsView. Real learners → answer-safe
          SnapshotQuizReview built from get_quiz_review (pass-gated snapshot). */}
      {activityReview && (
        <div
          onClick={() => setActivityReview(null)}
          style={{ position: "fixed", inset: 0, zIndex: 1000, background: "rgba(11,18,32,0.45)",
            display: "flex", alignItems: "center", justifyContent: "center", padding: 16, overflowY: "auto" }}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{ background: C.white, borderRadius: C.radius, width: "100%", maxWidth: 680,
              maxHeight: "90vh", overflowY: "auto", boxShadow: "0 8px 40px rgba(11,18,32,0.18)", padding: 24 }}
          >
            {activityReview.mode === "demo" ? (
              <QuizResultsView
                quiz={activityReview.quiz}
                attempt={activityReview.attempt}
                onRetake={() => { const id = activityReview.quiz.id; setActivityReview(null); onStartQuiz?.(id); }}
                onBack={() => setActivityReview(null)}
              />
            ) : activityReview.mode === "loading" ? (
              <LoadingState rows={3} message="Loading your results…" />
            ) : activityReview.mode === "error" ? (
              <ErrorState message="We couldn't load these results. Please try again." onRetry={() => setActivityReview(null)} />
            ) : activityReview.mode === "real" ? (
              <SnapshotQuizReview
                quizName={activityReview.quizName}
                attempt={activityReview.model.attempt}
                rows={activityReview.model.rows}
                reveal={activityReview.model.reveal}
                unavailable={activityReview.model.unavailable}
                onRetake={() => { const id = activityReview.quizId; setActivityReview(null); onStartQuiz?.(id); }}
                onBack={() => setActivityReview(null)}
              />
            ) : null}
          </div>
        </div>
      )}

    </div>
  );
}


