const diffColors = { Easy: C.green, Medium: C.orange, Hard: C.red };

// ── Due-date helpers ──────────────────────────────────────────────────────────
// Assignment Experience Priority 2 — diff now comes from assignmentEngine.js's
// daysUntilDue(), the same local-day-boundary comparison resolveAssignmentStatus()
// uses for its "overdue" status. Previously this function re-derived its own
// day math, which happened to be correct (local-midnight normalized) while the
// engine compared raw timestamps — the two only diverged because of that
// duplication, not because either one was wrong on its own. One definition now,
// shared, so "Due today" here and "Overdue" on a manager screen can never
// disagree about the same assignment again.
function getDueStatus(dueAtStr) {
  const diff = daysUntilDue(dueAtStr);
  if (diff == null) return null;

  if (diff < 0)  return { label: "Overdue",        color: C.red,    urgent: true  };
  if (diff === 0)return { label: "Due today",       color: C.red,    urgent: true  };
  if (diff <= 6) return { label: `Due in ${diff} day${diff!==1?"s":""}`, color: C.orange, urgent: diff<=2 };
  if (diff <= 7) return { label: "Due this week",   color: C.orange, urgent: false };
  if (diff <= 14)return { label: "Due next week",   color: C.textSub,urgent: false };
  return           { label: `Due in ${diff} days`,  color: C.textSub,urgent: false };
}

function getDueProgress(assignedAtStr, dueAtStr) {
  if (!assignedAtStr || !dueAtStr) return 0;
  const assigned = new Date(assignedAtStr); assigned.setHours(0,0,0,0);
  const due      = new Date(dueAtStr);      due.setHours(0,0,0,0);
  const now      = new Date();              now.setHours(0,0,0,0);
  const total    = due - assigned;
  const elapsed  = now - assigned;
  if (total <= 0) return 100;
  return Math.min(100, Math.max(0, Math.round((elapsed / total) * 100)));
}

// ── Scoring helpers shared by QuizTakingView + QuizResultsView ─────────────────
// One canonical definition of "was this answer correct" per question type, so
// taking a quiz and reviewing its results can never disagree. `selected` shapes
// by type: mc/tf → option index, type → string, slider → number,
// match → [{ leftIdx, rightIdx, rightText }], open → string
// (open is free-response/manually-graded; there is no in-app grader in the
// self-paced quiz flow, so it is never counted against the learner).
// Note: "pin" was removed as a question type (see legacy-compat note on
// QuizTakingView/QuizResultsView below) — any question of an unrecognized
// type falls to the default branch and is safely scored as incorrect
// rather than crashing.
function isAnswerCorrect(ques, selected) {
  switch (ques.type) {
    case "slider":
      return selected !== null && selected !== undefined
        && Math.abs(selected - (ques.correct ?? 5)) <= (ques.tolerance ?? 1);
    case "type":
      return typeof selected === "string"
        && (ques.acceptedAnswers ?? []).some(a =>
            a.trim().toLowerCase() === selected.trim().toLowerCase());
    case "match": {
      const pairs = ques.pairs ?? [];
      if (!pairs.length || !Array.isArray(selected) || selected.length !== pairs.length) return false;
      return selected.every(mp => pairs[mp.leftIdx]?.right === mp.rightText);
    }
    case "open":
      // Manually graded — never auto-marked wrong, but an unanswered question
      // still shouldn't count as "correct".
      return typeof selected === "string" && selected.trim().length > 0;
    case "mc":
    case "tf":
      return selected === ques.correct;
    default:
      // Unknown/unsupported question type (e.g. a legacy "pin" question after that
      // type was removed) — always score as incorrect. Never fall back to comparing
      // `selected`/`ques.correct` directly, since both can be `undefined` for a type
      // that no longer defines those fields, which would otherwise read as "correct".
      return false;
  }
}

// ── MatchCard ────────────────────────────────────────────────────────────────
// A single draggable "answer" card for the Matching question type. Hoisted to
// module scope — NOT defined inside QuizTakingView's render body — so its
// component identity is stable across renders. Defining it inline gave React
// a brand-new function/type on every re-render, and dragging triggers very
// frequent re-renders (one per pointermove): React would unmount + remount
// the card's real DOM node mid-gesture. That silently killed the drag — per
// the Pointer Events spec, capture is released the instant its element
// disconnects from the DOM, so after the very first pixel of movement the
// browser stopped routing pointer events to the (now-destroyed) captured
// node, and nothing else picked up move/up handling. The interaction never
// actually broke in an obvious way — it just silently degraded to "press
// down, nothing visibly follows, release does a click" i.e. click-to-place.
function MatchCard({ ri, placedLeftIdx, revealed, isPicked, isDragged, rightText, C, onStartDrag, onActivateKey, onUnplace }) {
  return (
    <div
      role="button"
      tabIndex={revealed ? -1 : 0}
      aria-pressed={isPicked}
      aria-label={placedLeftIdx != null
        ? `${rightText}, placed. Press Enter to pick up and move.`
        : `${rightText}. Press Enter to pick up, then Enter a prompt to place it.`}
      onPointerDown={e => onStartDrag(e, ri)}
      onKeyDown={e => { if (!revealed && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); onActivateKey(ri); } }}
      // A placed card sits inside its prompt's drop-zone div, which has its own
      // onClick (zone activation). Without stopping propagation, the native
      // click synthesized after pointerup would bubble to that zone and fire
      // zone-activation using a stale "picked" read — capable of silently
      // relocating a DIFFERENT already-picked card. This card's own pick/drag
      // behavior is fully handled by the pointer handlers above.
      onClick={e => e.stopPropagation()}
      style={{
        padding: "10px 12px", borderRadius: 10, display: "flex", alignItems: "center",
        justifyContent: "space-between", gap: 8, fontSize: 13, fontWeight: 600, color: C.text,
        background: isPicked ? C.orangeLight : C.cardBg,
        border: `2px solid ${isPicked ? C.orange : C.creamBorder}`,
        cursor: revealed ? "default" : "grab",
        opacity: isDragged ? 0.35 : 1,
        touchAction: "none", // so the browser doesn't scroll instead of dragging on touch
        userSelect: "none",
        boxShadow: isPicked ? "0 0 0 3px rgba(253,191,36,0.18)" : "none",
      }}
    >
      <span>{rightText}</span>
      {placedLeftIdx != null && !revealed && (
        <span
          role="button" tabIndex={0} aria-label="Remove from prompt"
          onClick={e => { e.stopPropagation(); onUnplace(ri); }}
          onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); e.stopPropagation(); onUnplace(ri); } }}
          style={{ color: C.textMuted, fontSize: 14, lineHeight: 1, cursor: "pointer", flexShrink: 0 }}
        >×</span>
      )}
    </div>
  );
}

// ── QuizTakingView ────────────────────────────────────────────────────────────
// Answer-confidentiality (migration 055): for real learners this view renders a
// SANITIZED quiz (no answer keys) and shows ONLY neutral "Answer locked"
// confirmation — never green/red correctness, the correct answer, explanations,
// targets/tolerance, accepted answers, or the matching solution — and never
// computes a client-side score/pass (the server grades). Demo mode passes
// `revealFeedback` to keep its original teach-as-you-go per-question feedback on
// its own canonical seed data. Default is the safe (neutral) mode: if the prop
// is ever omitted, a learner cannot leak an answer.
function QuizTakingView({ quiz, onComplete, onExit, revealFeedback = false }) {
  const mobile = useMobile(); // matching is the first two-column layout in this view — needs to stack on narrow screens
  const [qIdx,          setQIdx]          = useState(0);
  const [answers,       setAnswers]       = useState({});
  const [revealed,      setRevealed]      = useState(false);
  const [sliderDraft,   setSliderDraft]   = useState(null);
  const [textDraft,     setTextDraft]     = useState(""); // type-answer / open-response draft
  const [shuffledRight, setShuffledRight] = useState([]);     // shuffled q.pairs for the "matches" column
  const [matchPicked,   setMatchPicked]   = useState(null);   // rightIdx "picked up" via click/keyboard, awaiting a drop target
  const [matchDrag,     setMatchDrag]     = useState(null);   // { rightIdx, pointerId, x, y, moved, fromLeftIdx } while a pointer-drag is in flight
  const [matchOverZone, setMatchOverZone] = useState(null);   // leftIdx (number) | "pool" | null — drop zone currently hovered during a drag
  // Self-Paced Quiz Timers — seconds left on the CURRENT question, or null
  // when this question has no configured time limit (legacy questions saved
  // before timeLimit existed). Reset per-question in the effect below, same
  // place every other per-question draft already resets. Ralli Live has its
  // own independent timer state (RankdGameScreen/RankdLobbyScreen) — this is
  // a separate implementation for the self-paced flow only.
  const [timeLeft, setTimeLeft] = useState(null);
  // Self-Paced Quiz Timers — Map<questionId, secondsSpent>, only ever
  // populated for questions that had a timeLimit. Captured centrally (one
  // effect below, keyed on `revealed`) rather than in every individual
  // commit function (choose/commitSlider/commitType/commitOpen/commitMatch/
  // handleTimeUp) — whichever one fires, it always ends with setRevealed(true)
  // in the same synchronous handler as writing `answers`, so `timeLeft` at
  // the moment `revealed` flips true is always this question's true
  // remaining time, regardless of which path got there. Feeds the "time"
  // column in QuizResultsView's per-question review, which previously had no
  // timing data at all even for timed questions.
  const [answerTimes, setAnswerTimes] = useState({});

  // Task 15 — one stable idempotency key per quiz-taking session, generated
  // once and reused across any retry of the SAME submission (network retry,
  // double-click on Finish before the UI reacts). A genuine retake mounts a
  // fresh QuizTakingView (see retakeQuiz() in QuizzesScreen), which creates
  // a brand new ref/key — so retakes are never deduped against each other.
  const submissionIdRef = useRef(null);
  if (!submissionIdRef.current) {
    submissionIdRef.current = (typeof crypto !== "undefined" && crypto.randomUUID)
      ? crypto.randomUUID()
      : `sub-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  }
  // Timestamp of the last auto-advance — used to swallow a physical double-click
  // that would otherwise land a second commit on the freshly-shown next question.
  const advanceGuardRef = useRef(0);

  const q        = quiz.questions[qIdx];
  const total    = quiz.questions.length;
  const selected = answers[q.id] ?? null;
  const isLast   = qIdx === total - 1;
  const isSlider = q.type === "slider";
  const isType   = q.type === "type";
  const isMatch  = q.type === "match";
  const isOpen   = q.type === "open";
  // Any question whose type isn't one of the above (e.g. a legacy "pin" question
  // from before that type was removed) falls back to a safe, explicit notice
  // instead of silently rendering as a broken multiple-choice list.
  const isKnownType = isSlider || isType || isMatch || isOpen || q.type === "mc" || q.type === "tf";

  // Reset draft state when question changes
  useEffect(() => {
    setSliderDraft(null);
    setTextDraft("");
    setMatchPicked(null);
    setMatchDrag(null);
    setMatchOverZone(null);
    // Right-hand answer pool as an array of STRINGS. Learner-safe sanitized
    // quizzes already carry an INDEPENDENTLY SHUFFLED, decoupled `rightChoices`
    // (server-side, so the client never sees the pairing) — used as-is. Demo's
    // canonical `pairs` are shuffled here client-side, as before.
    setShuffledRight((() => {
      if (q.type !== "match") return [];
      const { rightChoices } = matchColumns(q);
      if (Array.isArray(q.rightChoices) && q.rightChoices.length) return rightChoices.slice();
      return [...rightChoices].sort(() => Math.random() - 0.5);
    })());
    // Self-Paced Quiz Timers — fresh countdown for the question that just
    // became active. A question with no timeLimit (legacy data) gets `null`,
    // which the countdown effect below treats as "no timer" rather than 0s.
    setTimeLeft(q.timeLimit > 0 ? q.timeLimit : null);
  }, [qIdx]); // eslint-disable-line react-hooks/exhaustive-deps

  // Self-Paced Quiz Timers — one-second countdown for the active question.
  // Stops counting once the question is revealed (answered, or already timed
  // out) and naturally stops on unmount/qIdx-change via the cleanup below —
  // covers "pauses when quiz completed" (unmounts on the last question's
  // Next → onComplete) and "pauses when view unmounts" (onExit).
  useEffect(() => {
    if (revealed || timeLeft == null) return;
    if (timeLeft <= 0) { handleTimeUp(); return; }
    const t = setTimeout(() => setTimeLeft(n => (n == null ? n : n - 1)), 1000);
    return () => clearTimeout(t);
  }, [timeLeft, revealed]); // eslint-disable-line react-hooks/exhaustive-deps

  // Self-Paced Quiz Timers — records how long this question actually took,
  // the instant it's revealed (answered manually or timed out). q.timeLimit
  // is null for legacy questions saved before timers existed, so those never
  // get an entry — QuizResultsView falls back to showing nothing for them,
  // same as today. Guards against double-write (harmless either way, but
  // keeps the map from churning on unrelated re-renders while revealed stays true).
  useEffect(() => {
    if (!revealed || !(q.timeLimit > 0)) return;
    setAnswerTimes(prev => (q.id in prev) ? prev : { ...prev, [q.id]: Math.max(0, q.timeLimit - (timeLeft ?? 0)) });
  }, [revealed]); // eslint-disable-line react-hooks/exhaustive-deps

  // Time's up — commit whatever answer already exists (a slider always has a
  // value; mc/tf/match write straight to `answers` as soon as something is
  // picked/placed, so there's nothing extra to do for those; type/open only
  // have an uncommitted value in `textDraft`) using the exact same shape the
  // manual Check/Submit buttons write, then reveal — same "existing safe
  // behavior" isAnswerCorrect() already applies to a null/partial answer.
  // Never auto-advances past reveal — the learner still sees feedback and
  // clicks Next themselves, same as answering manually.
  const handleTimeUp = () => {
    if (revealed) return;
    if ((q.type === "type" || q.type === "open") && textDraft.trim()) {
      setAnswers(prev => ({ ...prev, [q.id]: textDraft }));
    } else if (q.type === "slider") {
      setAnswers(prev => ({ ...prev, [q.id]: sliderVal }));
    }
    setRevealed(true);
  };

  // Slider helpers
  const sliderMin = q.min ?? 0;
  const sliderMax = q.max ?? 10;
  const sliderVal = sliderDraft !== null ? sliderDraft
    : (selected !== null ? selected : Math.round((sliderMin + sliderMax) / 2));

  // Match helpers. Prompts come from the sanitized `leftItems` (learner) or the
  // canonical `pairs` (demo). A canonical prompt also carries `.right` (the
  // solution) — referenced ONLY under `fb` (feedback) below, never in learner mode.
  const matchPairs   = Array.isArray(selected) ? selected : [];
  const matchPrompts = (Array.isArray(q.pairs) && q.pairs.length)
    ? q.pairs
    : matchColumns(q).leftItems.map(left => ({ left }));
  const matchAllDone = matchPrompts.length > 0 && matchPairs.length >= matchPrompts.length;
  const getPairForLeft  = (li) => matchPairs.find(mp => mp.leftIdx === li);
  const getPairForRight = (ri) => matchPairs.find(mp => mp.rightIdx === ri);

  // Feedback gating. `revealed` == this question is answered/locked (drives
  // progression + input disabling for BOTH modes). `fb` == also SHOW correctness
  // — demo only. In learner mode fb is always false, so no answer key, colour,
  // or explanation is ever read or rendered, and isAnswerCorrect() is never called.
  const showFeedback = !!revealFeedback;
  const fb = revealed && showFeedback;
  const isCorrect = fb && isAnswerCorrect(q, selected);

  // Swallow a physical double-click that lands just after an auto-advance (so it
  // can't answer+advance the freshly-shown next question). Same-question double
  // commits are already no-ops via the `revealed` guard.
  const justAdvanced = () => advanceGuardRef.current && (Date.now() - advanceGuardRef.current < 350);

  const choose = (idx) => {
    if (revealed || justAdvanced()) return;
    setAnswers(prev => ({ ...prev, [q.id]: idx }));
    setRevealed(true);
  };

  const commitSlider = () => {
    if (revealed || justAdvanced()) return;
    setAnswers(prev => ({ ...prev, [q.id]: sliderVal }));
    setRevealed(true);
  };

  const commitType = () => {
    if (revealed || justAdvanced() || !textDraft.trim()) return;
    setAnswers(prev => ({ ...prev, [q.id]: textDraft }));
    setRevealed(true);
  };

  const commitOpen = () => {
    if (revealed || justAdvanced() || !textDraft.trim()) return;
    setAnswers(prev => ({ ...prev, [q.id]: textDraft }));
    setRevealed(true);
  };

  // ── Matching: place/unplace/swap — shared by drag-and-drop AND the click/keyboard
  // fallback below, so both input methods always produce the exact same state shape
  // ({ leftIdx, rightIdx, rightText }[]) that isAnswerCorrect() and QuizResultsView
  // already score/display. Placement never auto-reveals — matching now requires an
  // explicit "Submit Matches" (commitMatch), same pattern as pin/slider.
  const placeMatchCard = (rightIdx, targetLeftIdx) => {
    if (revealed) return;
    setAnswers(prev => {
      const current    = Array.isArray(prev[q.id]) ? prev[q.id] : [];
      const sourcePair  = current.find(mp => mp.rightIdx === rightIdx);       // where this card is now (undefined = pool)
      // Dropping a card back onto the slot it already occupies is a no-op —
      // without this guard the code below would push the same {leftIdx,
      // rightIdx} pair a second time (it reads as both the "moved" card and
      // the "displaced" card), corrupting the answers array with a duplicate
      // entry and breaking isAnswerCorrect()'s length check for this question.
      if (sourcePair && sourcePair.leftIdx === targetLeftIdx) return prev;
      const targetPair  = current.find(mp => mp.leftIdx === targetLeftIdx);   // what's currently in the target slot (undefined = empty)
      const next = current.filter(mp => mp.rightIdx !== rightIdx && mp.leftIdx !== targetLeftIdx);
      next.push({ leftIdx: targetLeftIdx, rightIdx, rightText: shuffledRight[rightIdx] });
      if (targetPair && sourcePair) {
        // True swap: the card displaced from the target slot takes the dragged card's old slot.
        next.push({ leftIdx: sourcePair.leftIdx, rightIdx: targetPair.rightIdx, rightText: shuffledRight[targetPair.rightIdx] });
      }
      // If targetPair existed but sourcePair didn't (card came from the pool), the
      // displaced card simply isn't re-added — it returns to the pool.
      return { ...prev, [q.id]: next };
    });
  };

  const unplaceMatchCard = (rightIdx) => {
    if (revealed) return;
    setAnswers(prev => {
      const current = Array.isArray(prev[q.id]) ? prev[q.id] : [];
      return { ...prev, [q.id]: current.filter(mp => mp.rightIdx !== rightIdx) };
    });
  };

  const commitMatch = () => {
    if (revealed || justAdvanced() || !matchAllDone) return;
    setRevealed(true);
  };

  // Click / keyboard fallback (no pointer drag required): click a card to "pick" it
  // up, then click any drop zone (a prompt row, or the pool) to send it there.
  // Picking the already-picked card again releases it without moving anything.
  const handleCardActivate = (rightIdx) => {
    if (revealed) return;
    setMatchPicked(prev => (prev === rightIdx ? null : rightIdx));
  };
  const handleZoneActivate = (targetLeftIdx /* number | "pool" */) => {
    if (revealed || matchPicked === null) return;
    if (targetLeftIdx === "pool") unplaceMatchCard(matchPicked);
    else placeMatchCard(matchPicked, targetLeftIdx);
    setMatchPicked(null);
  };

  // Pointer-based drag (mouse + touch + pen, via the Pointer Events API — native
  // HTML5 drag-and-drop doesn't fire on touch devices, so this is hand-rolled).
  // Move/up tracking lives on `window`, not on the card element: `window` is
  // never unmounted, so the gesture can't be silently dropped by a remount
  // (see MatchCard's comment) or by the pointer traveling somewhere that
  // doesn't itself have a pointermove/pointerup handler (e.g. over a drop
  // zone, which only has onClick/onKeyDown). `matchDragRef` and
  // `matchHandlersRef` exist because the window listeners live outside
  // React's render cycle — reading `matchDrag` state or `placeMatchCard`
  // etc. via normal closures inside them would use whatever was current
  // when the listener was attached, not what's current when it actually
  // fires; the refs are mutated directly so every read is live.
  const MATCH_DRAG_THRESHOLD = 6; // px of movement before a press counts as a drag, not a click
  const matchDragRef     = useRef(null);
  const matchHandlersRef = useRef(null);
  useEffect(() => {
    matchHandlersRef.current = { placeMatchCard, unplaceMatchCard, handleCardActivate };
  }); // no deps — refreshed after every render so the window listeners always call the latest closures

  const startMatchDrag = (e, rightIdx) => {
    if (revealed) return;
    e.currentTarget.setPointerCapture?.(e.pointerId);
    const fromLeftIdx = getPairForRight(rightIdx)?.leftIdx ?? null;
    const initial = { rightIdx, pointerId: e.pointerId, x: e.clientX, y: e.clientY, startX: e.clientX, startY: e.clientY, moved: false, fromLeftIdx };
    matchDragRef.current = initial;
    setMatchDrag(initial);
    setMatchPicked(null); // dragging takes over from any pending click-pick
  };

  useEffect(() => {
    if (!matchDrag) return;
    const pointerId = matchDrag.pointerId;

    const zoneAt = (x, y) => {
      const el = document.elementFromPoint(x, y);
      const zoneEl = el?.closest?.("[data-match-zone]");
      const zone = zoneEl?.getAttribute("data-match-zone") ?? null;
      return zone === "pool" ? "pool" : zone !== null ? Number(zone) : null;
    };

    const handleMove = (e) => {
      if (e.pointerId !== pointerId) return;
      const cur = matchDragRef.current;
      if (!cur) return;
      const dx = e.clientX - cur.startX, dy = e.clientY - cur.startY;
      const moved = cur.moved || Math.hypot(dx, dy) > MATCH_DRAG_THRESHOLD;
      const next = { ...cur, x: e.clientX, y: e.clientY, moved };
      matchDragRef.current = next;
      setMatchDrag(next);
      if (moved) setMatchOverZone(zoneAt(e.clientX, e.clientY));
    };

    const handleUp = (e) => {
      if (e.pointerId !== pointerId) return;
      const cur = matchDragRef.current;
      matchDragRef.current = null;
      const handlers = matchHandlersRef.current;
      if (cur?.moved) {
        const zone = zoneAt(e.clientX, e.clientY);
        if (zone === "pool") handlers.unplaceMatchCard(cur.rightIdx);
        else if (zone !== null) handlers.placeMatchCard(cur.rightIdx, Number(zone));
        // else: dropped outside any zone — treat as cancelled, card stays where it was
      } else if (cur) {
        // No meaningful movement — this was a click/tap, not a drag.
        handlers.handleCardActivate(cur.rightIdx);
      }
      setMatchDrag(null);
      setMatchOverZone(null);
    };

    window.addEventListener("pointermove", handleMove);
    window.addEventListener("pointerup", handleUp);
    window.addEventListener("pointercancel", handleUp);
    return () => {
      window.removeEventListener("pointermove", handleMove);
      window.removeEventListener("pointerup", handleUp);
      window.removeEventListener("pointercancel", handleUp);
    };
  }, [matchDrag?.pointerId]); // eslint-disable-line react-hooks/exhaustive-deps

  const next = () => {
    if (isLast) {
      // Server-safe submission: one entry per question, matching decoupled to
      // {leftIdx, rightText}, NO canonical `correct`. This is exactly what
      // submit_quiz_attempt_atomic_v2 grades.
      const answerList = buildSubmissionAnswers(quiz.questions, answers, answerTimes);
      // Client score/pass are computed ONLY for demo (revealFeedback) — demo has
      // canonical seed data and no server. Real learners submit and let the
      // server grade; onComplete ignores any client score for real users, so we
      // leave them null here (there are no answer keys to score against anyway).
      let score = null, passed = null;
      if (showFeedback) {
        const gradedTotal  = quiz.questions.filter(ques => ques.type !== "open").length;
        const correctCount = quiz.questions.filter(ques =>
          ques.type !== "open" && isAnswerCorrect(ques, answers[ques.id] ?? null)
        ).length;
        score  = gradedTotal > 0 ? Math.round((correctCount / gradedTotal) * 100) : 100;
        passed = score >= (quiz.passingScore ?? 100);
      }
      const attempt = { id: `at${Date.now()}`, date: new Date().toISOString().slice(0,10), score, passed, answers: answerList, submissionId: submissionIdRef.current };
      onComplete(attempt);
    } else {
      // Self-Paced Quiz Timers — reset timeLeft in this SAME batch as
      // revealed=false, not via the separate qIdx-keyed effect further down.
      // That effect only runs after the next render, so on the render in
      // between, the countdown effect would see this question's leftover
      // stale timeLeft (often 0, if the previous question's timer had just
      // expired) paired with the freshly-false `revealed` — and immediately
      // fire handleTimeUp() for the new question before its real timer ever
      // started. Setting it here closes that race; the qIdx effect still
      // runs too and just redundantly confirms the same value.
      const nextQ = quiz.questions[qIdx + 1];
      setTimeLeft(nextQ?.timeLimit > 0 ? nextQ.timeLimit : null);
      setQIdx(i => i + 1);
      setRevealed(false);
    }
  };

  // Learner-mode auto-advance: when NO feedback is shown (real learner attempt),
  // a committed answer must advance to the next question immediately — no
  // separate "Next Question" click (which, with feedback hidden, read as the
  // same question being asked twice). The answer is already committed to
  // `answers`/`revealed` before this runs, so the FINAL question's submit builds
  // the complete answer list through the existing canonical path. When feedback
  // IS shown (demo/authorized preview), Submit → feedback → Next is preserved.
  // useLayoutEffect advances before paint, so the locked-but-unadvanced frame
  // never flashes. Fires exactly once per commit (guarded on `revealed`); the
  // last question routes through next()→onComplete (double-submit-safe upstream).
  React.useLayoutEffect(() => {
    if (!revealed || showFeedback) return;
    advanceGuardRef.current = Date.now();
    next();
  }, [revealed]); // eslint-disable-line react-hooks/exhaustive-deps

  // Learner mode shows NO per-question message once an answer is locked — the
  // learner's own selection stays visible (highlighted option / disabled input /
  // placed cards) and the Next button appears immediately, with no "Answer
  // locked" text, no correctness, and no feedback pause.

  return (
    <div style={{ maxWidth: 640, margin: "0 auto", display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
        <button onClick={onExit} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0 }}>← Exit</button>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          {/* Self-Paced Quiz Timers — hidden once revealed (question is answered/
              timed out) and hidden entirely for legacy questions with no
              configured time limit, rather than showing a fake "0s". */}
          {timeLeft != null && !revealed && (() => {
            const timerPct = q.timeLimit > 0 ? (timeLeft / q.timeLimit) * 100 : 0;
            const timerColor = timerPct > 50 ? C.trueGreen : timerPct > 25 ? C.orange : "#EF4444";
            return (
              <div
                role="timer" aria-live="polite" aria-label={`${timeLeft} seconds remaining`}
                style={{
                  width: 30, height: 30, borderRadius: "50%", flexShrink: 0,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  border: `2px solid ${timerColor}`, background: `${timerColor}14`,
                  transition: "border-color 0.5s, background 0.5s",
                }}
              >
                <span style={{ fontSize: 12, fontWeight: 900, color: timerColor }}>{timeLeft}</span>
              </div>
            );
          })()}
          <span style={{ fontSize: 12, fontWeight: 700, color: C.textMuted }}>{qIdx + 1} / {total}</span>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: 6, borderRadius: 99, background: C.muted, overflow: "hidden" }}>
        <div style={{ height: "100%", borderRadius: 99, background: C.orange, width: `${((qIdx + (revealed ? 1 : 0)) / total) * 100}%`, transition: "width 0.3s" }} />
      </div>

      {/* Question */}
      <Card>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 12 }}>Question {qIdx + 1}</div>
        <p style={{ margin: "0 0 20px", fontSize: 16, fontWeight: 700, color: C.text, lineHeight: 1.5 }}>{q.text || q.q}</p>

        {isType ? (
          /* ── Type Answer ── */
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <input
              type="text"
              placeholder="Type your answer…"
              value={revealed ? (typeof selected === "string" ? selected : "") : textDraft}
              disabled={revealed}
              onChange={e => !revealed && setTextDraft(e.target.value)}
              onKeyDown={e => e.key === "Enter" && !revealed && commitType()}
              autoFocus
              style={{
                width: "100%", boxSizing: "border-box", padding: "14px 16px", borderRadius: 12,
                border: `2px solid ${fb ? (isCorrect ? C.trueGreen : "#EF4444") : C.creamBorder}`,
                background: fb ? (isCorrect ? "#DCFCE7" : "#FEE2E2") : C.pageBg,
                color: C.text, fontSize: 15, fontWeight: 600, outline: "none", fontFamily: "inherit",
              }}
            />
            {fb ? (
              <div style={{ padding: "10px 14px", borderRadius: 10, background: isCorrect ? "#F0FDF4" : "#FFF7ED", border: `1px solid ${isCorrect ? "#86EFAC" : C.creamBorder}`, fontSize: 13 }}>
                {isCorrect
                  ? <strong style={{ color: "#166534" }}>Correct!</strong>
                  : <><strong style={{ color: C.orange }}>Accepted: </strong><span style={{ color: C.textSub }}>{(q.acceptedAnswers ?? []).join(", ")}</span></>
                }
                {q.explanation && <p style={{ margin: "6px 0 0", fontSize: 12, color: C.textSub, lineHeight: 1.6 }}>{q.explanation}</p>}
              </div>
            ) : null}
            {!revealed && (
              <button onClick={commitType} disabled={!textDraft.trim()} style={{
                padding: "12px 28px", borderRadius: 12, border: "none", alignSelf: "flex-end",
                background: textDraft.trim() ? C.orange : C.muted,
                color: textDraft.trim() ? "#fff" : C.textMuted,
                fontSize: 14, fontWeight: 700, cursor: textDraft.trim() ? "pointer" : "default",
              }}>
                {showFeedback ? "Check Answer" : "Submit Answer"}
              </button>
            )}
          </div>
        ) : isSlider ? (
          /* ── Slider ── */
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ textAlign: "center" }}>
              <span style={{ fontSize: 36, fontWeight: 900, lineHeight: 1, color: fb ? (isCorrect ? "#166534" : C.red) : C.orange }}>{sliderVal}</span>
              <div style={{ fontSize: 12, color: C.textMuted, marginTop: 4 }}>{sliderMin} – {sliderMax}</div>
            </div>
            <input type="range" min={sliderMin} max={sliderMax} step={q.step ?? 1} value={sliderVal} disabled={revealed}
              onChange={e => !revealed && setSliderDraft(Number(e.target.value))}
              style={{ width: "100%", accentColor: C.orange, cursor: revealed ? "default" : "pointer" }}
            />
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: C.textMuted }}>
              <span>{q.minLabel ? `${q.minLabel} (${sliderMin})` : sliderMin}</span>
              <span>{q.maxLabel ? `${q.maxLabel} (${sliderMax})` : sliderMax}</span>
            </div>
            {fb ? (
              <div style={{ padding: "10px 14px", borderRadius: 10, background: isCorrect ? "#F0FDF4" : "#FFF7ED", border: `1px solid ${isCorrect ? "#86EFAC" : C.creamBorder}`, fontSize: 13, color: C.text }}>
                <strong style={{ color: isCorrect ? "#166534" : C.orange }}>
                  {isCorrect ? `Correct! Target: ${q.correct ?? 5} ±${q.tolerance ?? 1}` : `Target was ${q.correct ?? 5} ±${q.tolerance ?? 1}.`}
                </strong>
                {!isCorrect && <span style={{ color: C.textSub }}> You answered {selected}.</span>}
              </div>
            ) : null}
            {fb && q.explanation && (
              <div style={{ padding: "12px 16px", borderRadius: 10, background: C.pageBg, border: `1px solid ${C.creamBorder}` }}>
                <p style={{ margin: 0, fontSize: 13, color: C.text, lineHeight: 1.6 }}>{q.explanation}</p>
              </div>
            )}
            {!revealed && (
              <button onClick={commitSlider} style={{ padding: "12px 28px", borderRadius: 12, border: "none", background: C.orange, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer", alignSelf: "flex-end" }}>
                {showFeedback ? "Check Answer" : "Submit Answer"}
              </button>
            )}
          </div>
        ) : !isKnownType ? (
          /* ── Legacy/unsupported question type ──
             Reached only if a quiz contains a question whose type has since been
             removed from the product (e.g. old "pin" questions). Never falls through
             to the MC/TF options list — that produced a real bug once already when a
             type had no explicit branch. Assignment/manager tooling is expected to
             replace or delete this question; taking it here just can't be scored. */
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <div style={{ padding: 16, borderRadius: 12, background: "#FFF7ED", border: `1px solid ${C.creamBorder}` }}>
              <p style={{ margin: 0, fontSize: 14, fontWeight: 700, color: C.text }}>This question type is no longer supported.</p>
              <p style={{ margin: "6px 0 0", fontSize: 13, color: C.textSub, lineHeight: 1.5 }}>
                It won't be scored. Ask your manager to update this quiz.
              </p>
            </div>
            {!revealed && (
              <button onClick={() => setRevealed(true)} style={{
                padding: "12px 28px", borderRadius: 12, border: "none", alignSelf: "flex-end",
                background: C.orange, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer",
              }}>
                Continue
              </button>
            )}
          </div>
        ) : isMatch ? (
          /* ── Matching (drag-and-drop, with a click/keyboard fallback) ──
             Left prompts stay fixed. Right answers are draggable cards that start in
             the "Answers" pool and move into a prompt's drop zone. Cards can be
             re-dragged (or re-clicked) to a different prompt or back to the pool at
             any time before Submit — correctness is never revealed until then. */
          (() => {
            const unplacedRight = shuffledRight
              .map((pair, ri) => ({ pair, ri }))
              .filter(({ ri }) => !getPairForRight(ri));

            // Ghost card during an active drag reuses this — MatchCard itself covers
            // the two real card states (in the pool / placed in a prompt).
            const ghostCardStyle = {
              padding: "10px 12px", borderRadius: 10, display: "flex", alignItems: "center",
              justifyContent: "space-between", gap: 8, fontSize: 13, fontWeight: 600, color: C.text,
              background: C.cardBg, border: `2px solid ${C.creamBorder}`,
              cursor: "grabbing", boxShadow: "0 8px 20px rgba(11,18,32,0.25)",
            };

            return (
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div style={{ display: "flex", flexDirection: mobile ? "column" : "row", gap: 14 }}>
                  {/* Left — fixed prompts, each with an adjacent drop zone */}
                  <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 8 }}>
                    <p style={{ margin: "0 0 4px", fontSize: 10, fontWeight: 700, color: C.textMuted, textTransform: "uppercase", letterSpacing: "0.08em" }}>Prompts</p>
                    {matchPrompts.map((pair, li) => {
                      const pairInfo  = getPairForLeft(li);
                      // Correctness (pair.right) is ONLY known/shown in demo feedback mode.
                      const isRevealCorrect = fb && pairInfo && pairInfo.rightText === pair.right;
                      const isRevealWrong   = fb && pairInfo && pairInfo.rightText !== pair.right;
                      const isOver = matchOverZone === li;
                      const canDrop = matchPicked !== null || (matchDrag && matchDrag.moved);
                      let zoneBorder = C.creamBorder, zoneBg = "transparent";
                      if (isRevealCorrect)    { zoneBorder = C.trueGreen; zoneBg = "#DCFCE7"; }
                      else if (isRevealWrong) { zoneBorder = "#EF4444";   zoneBg = "#FEE2E2"; }
                      else if (isOver)        { zoneBorder = C.orange;   zoneBg = C.orangeLight; }
                      return (
                        <div key={li} style={{ display: "flex", alignItems: "stretch", gap: 8 }}>
                          <div style={{
                            flex: "0 0 auto", minWidth: 96, padding: "10px 12px", borderRadius: 10,
                            border: `2px solid ${C.creamBorder}`, background: C.pageBg,
                            display: "flex", alignItems: "center", gap: 8,
                          }}>
                            <div style={{ width: 22, height: 22, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 800, background: isRevealCorrect ? C.trueGreen : isRevealWrong ? "#EF4444" : C.muted, color: (isRevealCorrect || isRevealWrong) ? "#fff" : C.textMuted }}>
                              {isRevealCorrect ? "✓" : isRevealWrong ? "✗" : String.fromCharCode(65 + li)}
                            </div>
                            <span style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{pair.left}</span>
                          </div>
                          {/* Drop zone — beside its prompt */}
                          <div
                            data-match-zone={li}
                            role="button" tabIndex={revealed || matchPicked === null ? -1 : 0}
                            aria-label={pairInfo ? `Drop zone for ${pair.left}, currently holds ${pairInfo.rightText}` : `Empty drop zone for ${pair.left}`}
                            onClick={() => handleZoneActivate(li)}
                            onKeyDown={e => { if ((e.key === "Enter" || e.key === " ") && matchPicked !== null) { e.preventDefault(); handleZoneActivate(li); } }}
                            style={{
                              flex: 1, minWidth: 0, borderRadius: 10,
                              border: `2px dashed ${pairInfo ? "transparent" : (isOver ? C.orange : C.creamBorder)}`,
                              background: !pairInfo && isOver ? C.orangeLight : "transparent",
                              display: "flex", alignItems: "stretch",
                              padding: pairInfo ? 0 : "10px 12px",
                              cursor: (canDrop && !revealed) ? "pointer" : "default",
                            }}
                          >
                            {pairInfo
                              ? <div style={{ flex: 1 }}>
                                  <MatchCard
                                    ri={pairInfo.rightIdx} placedLeftIdx={li} revealed={revealed} C={C}
                                    isPicked={matchPicked === pairInfo.rightIdx}
                                    isDragged={matchDrag?.rightIdx === pairInfo.rightIdx && matchDrag.moved}
                                    rightText={shuffledRight[pairInfo.rightIdx]}
                                    onStartDrag={startMatchDrag} onActivateKey={handleCardActivate} onUnplace={unplaceMatchCard}
                                  />
                                </div>
                              : <span style={{ fontSize: 12, color: C.textMuted, fontStyle: "italic", alignSelf: "center" }}>
                                  {matchPicked !== null ? "Tap to drop here" : "Drop answer here"}
                                </span>
                            }
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  {/* Right — pool of unplaced draggable answer cards */}
                  <div style={{ flex: mobile ? "1 1 auto" : "0 0 40%", display: "flex", flexDirection: "column", gap: 8 }}>
                    <p style={{ margin: "0 0 4px", fontSize: 10, fontWeight: 700, color: C.textMuted, textTransform: "uppercase", letterSpacing: "0.08em" }}>
                      Answers {unplacedRight.length > 0 ? `(${unplacedRight.length} left)` : ""}
                    </p>
                    <div
                      data-match-zone="pool"
                      role="button" tabIndex={revealed || matchPicked === null ? -1 : 0}
                      aria-label="Answer pool — drop here to remove a placed answer"
                      onClick={() => handleZoneActivate("pool")}
                      onKeyDown={e => { if ((e.key === "Enter" || e.key === " ") && matchPicked !== null) { e.preventDefault(); handleZoneActivate("pool"); } }}
                      style={{
                        flex: 1, display: "flex", flexDirection: "column", gap: 8, minHeight: 60,
                        borderRadius: 10, padding: 8,
                        border: `2px dashed ${matchOverZone === "pool" ? C.orange : "transparent"}`,
                        background: matchOverZone === "pool" ? C.orangeLight : "transparent",
                      }}
                    >
                      {unplacedRight.length === 0 ? (
                        <p style={{ margin: 0, fontSize: 12, color: C.textMuted, fontStyle: "italic" }}>All answers placed.</p>
                      ) : unplacedRight.map(({ ri }) => (
                        <MatchCard
                          key={ri} ri={ri} placedLeftIdx={null} revealed={revealed} C={C}
                          isPicked={matchPicked === ri}
                          isDragged={matchDrag?.rightIdx === ri && matchDrag.moved}
                          rightText={shuffledRight[ri]}
                          onStartDrag={startMatchDrag} onActivateKey={handleCardActivate} onUnplace={unplaceMatchCard}
                        />
                      ))}
                    </div>
                  </div>
                </div>

                {/* Floating drag ghost — follows the pointer while a real drag is in progress */}
                {matchDrag && matchDrag.moved && (
                  <div style={{
                    position: "fixed", left: matchDrag.x, top: matchDrag.y, transform: "translate(-50%, -50%)",
                    zIndex: 2000, pointerEvents: "none", width: 180,
                  }}>
                    <div style={ghostCardStyle}>
                      <span>{shuffledRight[matchDrag.rightIdx]}</span>
                    </div>
                  </div>
                )}

                {!revealed && (
                  <>
                    <p style={{ margin: 0, fontSize: 11, color: C.textMuted }}>
                      Drag each answer into place, or select an answer and then choose a row. Enter or Space works the same way from the keyboard.
                    </p>
                    <button onClick={commitMatch} disabled={!matchAllDone} style={{
                      padding: "12px 28px", borderRadius: 12, border: "none", alignSelf: "flex-end",
                      background: matchAllDone ? C.orange : C.muted,
                      color: matchAllDone ? "#fff" : C.textMuted,
                      fontSize: 14, fontWeight: 700, cursor: matchAllDone ? "pointer" : "default",
                    }}>
                      {matchAllDone ? "Submit Matches" : `Place all ${matchPrompts.length} answers to continue`}
                    </button>
                  </>
                )}
              </div>
            );
          })()
        ) : isOpen ? (
          /* ── Open Ended ── */
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <textarea
              value={revealed ? (typeof selected === "string" ? selected : "") : textDraft}
              disabled={revealed}
              onChange={e => !revealed && setTextDraft(e.target.value)}
              placeholder="Type your response…"
              rows={4}
              style={{
                width: "100%", boxSizing: "border-box", padding: "14px 16px", borderRadius: 12, resize: "none",
                border: `2px solid ${revealed ? C.creamBorder : C.creamBorder}`,
                background: revealed ? C.pageBg : C.cardBg,
                color: C.text, fontSize: 14, fontWeight: 500, outline: "none", fontFamily: "inherit", lineHeight: 1.5,
              }}
            />
            {revealed && (
              <div style={{ padding: "10px 14px", borderRadius: 10, background: C.pageBg, border: `1px solid ${C.creamBorder}`, fontSize: 13, color: C.textSub }}>
                <strong style={{ color: C.text }}>Submitted.</strong> Open-ended answers are reviewed manually and aren't auto-scored.
              </div>
            )}
            {!revealed && (
              <button onClick={commitOpen} disabled={!textDraft.trim()} style={{
                padding: "12px 28px", borderRadius: 12, border: "none", alignSelf: "flex-end",
                background: textDraft.trim() ? C.orange : C.muted,
                color: textDraft.trim() ? "#fff" : C.textMuted,
                fontSize: 14, fontWeight: 700, cursor: textDraft.trim() ? "pointer" : "default",
              }}>
                Submit Response
              </button>
            )}
          </div>
        ) : (
          /* ── MC / TF ── */
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {(q.options ?? []).map((opt, i) => {
              const optLabel = typeof opt === "string" ? opt.trim()
                : opt !== null && typeof opt === "object"
                  ? String(opt.text || opt.label || opt.answer || opt.option || opt.value || "").trim()
                : String(opt ?? "").trim();
              const isBlank     = !optLabel.trim();
              const isSelected  = selected === i;
              const isRight     = fb && i === q.correct;
              const isThisWrong = fb && isSelected && i !== q.correct;
              // Neutral "this is the answer I locked in" highlight — shown before
              // reveal (both modes) and, in learner mode, after locking too. It
              // conveys the learner's own choice, never correctness.
              const isPick      = isSelected && (!revealed || !showFeedback);
              if (isBlank) console.warn("[ralli] Invalid quiz option", { quizId: quiz.id, questionId: q.id, optionIndex: i, originalOption: opt });
              let bg = C.cardBg, border = C.creamBorder, color = C.text;
              if (isRight)     { bg = "#DCFCE7"; border = C.trueGreen; color = "#166534"; }
              if (isThisWrong) { bg = "#FEE2E2"; border = "#EF4444";   color = "#991B1B"; }
              if (isPick)      { bg = C.orangeLight; border = C.orange; }
              if (isBlank)     { bg = C.pageBg;  border = C.muted; }
              return (
                <button key={i} onClick={() => !isBlank && choose(i)} disabled={isBlank} style={{
                  display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderRadius: 12,
                  border: `2px solid ${border}`, background: bg,
                  cursor: revealed || isBlank ? "default" : "pointer", textAlign: "left", width: "100%",
                  transition: "all 0.15s", opacity: isBlank ? 0.45 : 1,
                }}>
                  <div style={{ width: 28, height: 28, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 800, background: isRight ? C.trueGreen : isThisWrong ? "#EF4444" : isPick ? C.orange : C.muted, color: (isRight || isThisWrong || isPick) ? "#fff" : C.textMuted }}>
                    {isRight ? "✓" : isThisWrong ? "✗" : String.fromCharCode(65 + i)}
                  </div>
                  {isBlank
                    ? <span style={{ fontSize: 13, fontWeight: 600, color: C.textMuted, fontStyle: "italic" }}>Answer option missing</span>
                    : <span style={{ fontSize: 14, fontWeight: 600, color }}>{optLabel}</span>
                  }
                </button>
              );
            })}
          </div>
        )}

        {/* Explanation — MC/TF/Match only, DEMO feedback mode only (learner mode
            never reveals the explanation). Slider/type show feedback inline;
            open isn't graded; unsupported types show their own notice. */}
        {fb && !isSlider && !isType && !isOpen && isKnownType && q.explanation && (
          <div style={{ marginTop: 16, padding: "12px 16px", borderRadius: 10, background: isCorrect ? "#F0FDF4" : "#FFF7ED", border: `1px solid ${isCorrect ? "#86EFAC" : C.creamBorder}` }}>
            <p style={{ margin: 0, fontSize: 13, color: C.text, lineHeight: 1.6 }}><strong style={{ color: isCorrect ? "#166534" : C.orange }}>{isCorrect ? "Correct" : "Not quite"}.</strong> {q.explanation}</p>
          </div>
        )}
      </Card>

      {/* Next / Finish — shown after reveal */}
      {revealed && (
        <button onClick={next} style={{ alignSelf: "flex-end", padding: "12px 28px", borderRadius: 12, border: "none", background: C.orange, color: "#fff", fontSize: 14, fontWeight: 700, cursor: "pointer" }}>
          {isLast ? "See Results →" : "Next Question →"}
        </button>
      )}
    </div>
  );
}

// ── QuizResultsView ───────────────────────────────────────────────────────────
function QuizResultsView({ quiz, attempt, onRetake, onBack, showRetake = true, showBack = true, backLabel = "← Back to Quizzes", subtitle = null }) {
  const total = quiz.questions.length; // includes open-ended, for the review list below
  // Score denominator excludes open-ended (manually graded, never auto right/wrong) —
  // mirrors the same exclusion QuizTakingView.next() applies when computing attempt.score,
  // so the score shown here and the score already saved to quiz_attempts never disagree.
  const gradedTotal = quiz.questions.filter(q => q.type !== "open").length;
  const correct = attempt.answers.filter((a, i) =>
    quiz.questions[i].type !== "open" && isAnswerCorrect(quiz.questions[i], a.selected)
  ).length;
  const passed  = attempt.passed;
  // Effective passing score for display — must mirror the exact fallback rule
  // QuizTakingView.next() uses when computing the provisional attempt.passed
  // (quiz.passingScore ?? 100) AND the server's authoritative default
  // (COALESCE(passing_score, 100), migration 054), so the copy shown here can
  // never disagree with either. Default is 100 per PRODUCT_DECISIONS.md; quizzes
  // with a saved passing_score keep whatever was set.
  const effectivePassingScore = typeof quiz.passingScore === "number" ? quiz.passingScore : 100;

  return (
    <div style={{ maxWidth: 640, margin: "0 auto", display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Back */}
      {showBack && (
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0, alignSelf: "flex-start" }}>{backLabel}</button>
      )}

      {/* Score card */}
      <Card style={{ textAlign: "center", padding: "32px 24px" }}>
        <div style={{ fontSize: 52, fontWeight: 900, color: passed ? C.trueGreen : C.red, lineHeight: 1 }}>{attempt.score}%</div>
        <div style={{ marginTop: 8, marginBottom: 4, fontSize: 16, fontWeight: 800, color: C.text }}>{quiz.title}</div>
        {subtitle && <div style={{ fontSize: 12, color: C.textMuted, marginBottom: 4 }}>{subtitle}</div>}
        <div style={{ fontSize: 13, color: C.textSub, marginBottom: 16 }}>{correct} of {gradedTotal} correct · {attempt.date}</div>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, padding: "6px 16px", borderRadius: 99, background: passed ? "#DCFCE7" : "#FEE2E2", border: `1px solid ${passed ? "#86EFAC" : "#FCA5A5"}` }}>
          <span style={{ fontSize: 13, fontWeight: 800, color: passed ? "#166534" : "#991B1B" }}>{passed ? "Passed" : "Retry"}</span>
        </div>
        {!passed && showRetake && <p style={{ margin: "12px 0 0", fontSize: 12, color: C.textMuted }}>Score {effectivePassingScore}% or higher to pass. You've got this.</p>}
        {showRetake && onRetake && (
          <button onClick={onRetake} style={{ marginTop: 20, padding: "10px 24px", borderRadius: 10, border: `1px solid ${C.orange}`, background: C.orangeLight, color: C.orange, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
            Retake Quiz
          </button>
        )}
      </Card>

      {/* Per-question breakdown */}
      <div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 12 }}>Question Review</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {quiz.questions.map((q, i) => {
            const ans       = attempt.answers.find(a => a.questionId === q.id);
            const isSliderQ = q.type === "slider";
            const isTypeQ   = q.type === "type";
            const isMatchQ  = q.type === "match";
            const isOpenQ   = q.type === "open";
            // A question whose type no longer exists (e.g. a legacy "pin" question) —
            // never crash the results view, just show it as unscored.
            const isKnownQ  = isSliderQ || isTypeQ || isMatchQ || isOpenQ || q.type === "mc" || q.type === "tf";

            const wasRight = isAnswerCorrect(q, ans?.selected);
            const hasAnswer = isMatchQ
              ? Array.isArray(ans?.selected) && ans.selected.length > 0
              : (ans?.selected !== null && ans?.selected !== undefined);

            const answerLabel = isSliderQ
              ? (ans?.selected != null ? String(ans.selected) : null)
              : isTypeQ
              ? (typeof ans?.selected === "string" ? ans.selected : null)
              : isOpenQ
              ? (typeof ans?.selected === "string" ? ans.selected : null)
              : isMatchQ
              ? null // rendered as a per-pair breakdown below instead of a single line
              : !isKnownQ
              ? null
              : ((q.options ?? [])[ans?.selected] || null);

            const correctLabel = isSliderQ
              ? `${q.correct ?? 5} ±${q.tolerance ?? 1}`
              : isTypeQ
              ? ((q.acceptedAnswers ?? []).join(", ") || null)
              : isOpenQ
              ? null // no "correct" answer to compare against — manually graded
              : isMatchQ
              ? null
              : !isKnownQ
              ? null
              : ((q.options ?? [])[q.correct] || null);

            // Neutral (non red/green) treatment for open-ended (not auto-graded) and
            // for unsupported legacy types (never scored, never counted against the learner).
            const badgeBg   = (isOpenQ || !isKnownQ) ? C.muted   : wasRight ? "#DCFCE7" : "#FEE2E2";
            const badgeColor= (isOpenQ || !isKnownQ) ? C.textSub : wasRight ? "#166534" : "#991B1B";
            const badgeText = !isKnownQ ? "Unsupported" : isOpenQ ? (hasAnswer ? "Submitted" : "Skipped") : (wasRight ? "Correct" : "Incorrect");
            const borderColor = (isOpenQ || !isKnownQ) ? C.creamBorder : wasRight ? C.trueGreen : C.red;

            // "Time if applicable" — only for questions that actually had a
            // timeLimit configured (legacy questions saved before timers
            // existed have none, so this simply doesn't render for them,
            // same as every other type-conditional field on this card).
            // ans?.timeSpent is only present on attempts taken after this
            // was added; older attempts on a still-timed question fall back
            // to just showing the limit rather than a false "0s".
            const timeLabel = q.timeLimit > 0
              ? (ans?.timeSpent != null ? `Answered in ${ans.timeSpent}s (limit ${q.timeLimit}s)` : `Time limit: ${q.timeLimit}s`)
              : null;

            return (
              <Card key={q.id} style={{ borderLeft: `4px solid ${borderColor}` }}>
                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 4 }}>
                  <p style={{ margin: 0, fontSize: 14, fontWeight: 600, color: C.text, lineHeight: 1.5 }}>{i+1}. {q.text || q.q}</p>
                  <span style={{ fontSize: 12, fontWeight: 700, color: badgeColor, flexShrink: 0, padding: "2px 8px", borderRadius: 99, background: badgeBg }}>{badgeText}</span>
                </div>
                {timeLabel && (
                  <div style={{ fontSize: 11, color: C.textMuted, marginBottom: 8 }}>{timeLabel}</div>
                )}

                {/* Matching — per-pair breakdown */}
                {isMatchQ && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: q.explanation ? 8 : 0 }}>
                    {(q.pairs ?? []).map((pair, li) => {
                      const mp = (ans?.selected ?? []).find(m => m.leftIdx === li);
                      const pairOk = !!mp && mp.rightText === pair.right;
                      return (
                        <div key={li} style={{ fontSize: 13, color: pairOk ? "#166534" : "#991B1B" }}>
                          <strong>{pair.left}</strong> → {mp ? mp.rightText : <em style={{ color: C.textMuted }}>no match</em>}
                          {!pairOk && <span style={{ color: "#166534" }}> (correct: {pair.right})</span>}
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* User answer (non-matching types) */}
                {!isMatchQ && hasAnswer && (
                  <div style={{ fontSize: 13, color: isOpenQ ? C.textSub : (wasRight ? "#166534" : "#991B1B"), marginBottom: (wasRight || isOpenQ) ? 0 : 4 }}>
                    <strong>Your answer:</strong> {answerLabel || <em style={{ color: C.textMuted }}>—</em>}
                  </div>
                )}
                {!isMatchQ && !hasAnswer && (
                  <div style={{ fontSize: 13, color: C.textMuted }}>
                    <em>{isKnownQ ? "No answer submitted." : "This question type is no longer supported and wasn't scored."}</em>
                  </div>
                )}

                {/* Correct answer (only if wrong and a target exists) */}
                {!isMatchQ && !wasRight && !isOpenQ && correctLabel && (
                  <div style={{ fontSize: 13, color: "#166534", marginBottom: q.explanation ? 8 : 0 }}>
                    <strong>Correct answer:</strong> {correctLabel}
                  </div>
                )}

                {/* Explanation */}
                {q.explanation && (
                  <div style={{ marginTop: 8, padding: "10px 12px", borderRadius: 8, background: C.pageBg, border: `1px solid ${C.creamBorder}` }}>
                    <p style={{ margin: 0, fontSize: 12, color: C.textSub, lineHeight: 1.6 }}>{q.explanation}</p>
                  </div>
                )}
              </Card>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ── SnapshotQuizReview ────────────────────────────────────────────────────────
// Answer-confidentiality-safe results/review renderer (migration 055). Used for
// the real learner's post-submit results + Home history review, and the manager
// drill-down. It NEVER recomputes correctness client-side and NEVER reads the
// quiz's current mutable questions:
//   • per-question right/wrong comes from the server's stored `isCorrect`;
//   • the correct answer / explanation is shown ONLY when `reveal` is true and
//     ONLY from the immutable per-attempt snapshot (`row.solution`);
//   • when reveal is expected but the snapshot is absent (legacy / pre-snapshot),
//     `unavailable` shows an honest "Exact historical answer detail unavailable"
//     — the current quiz is never substituted for historical truth.
// `rows` is the output of reviewRows(); `attempt` supplies the authoritative
// score/pass for the header card.
function SnapshotQuizReview({
  quizName, attempt, rows = [], reveal = false, unavailable = false, points = null,
  onRetake, onBack, showRetake = true, showBack = true, backLabel = "← Back to Quizzes", subtitle = null,
  // Detailed review can load AFTER the (already-accepted) score/pass: 'ready'
  // shows the rows; 'loading'/'error' keep the server score visible while the
  // per-question detail is fetched/retried — the score/pass is never lost and
  // a review-fetch failure NEVER triggers a resubmit.
  reviewStatus = "ready", onRetryReview = null,
}) {
  const gradedRows  = rows.filter(r => r.type !== "open");
  const correctCount = rows.filter(r => r.isCorrect === true).length;
  const passed = !!attempt?.passed;
  const score  = attempt?.score;

  const optionLabel = (opts, idx) =>
    (Array.isArray(opts) && idx != null && opts[idx] != null) ? String(opts[idx]) : (idx != null ? `Option ${Number(idx) + 1}` : null);

  return (
    <div style={{ maxWidth: 640, margin: "0 auto", display: "flex", flexDirection: "column", gap: 20 }}>
      {showBack && (
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0, alignSelf: "flex-start" }}>{backLabel}</button>
      )}

      {/* Score card — server-authoritative score/pass */}
      <Card style={{ textAlign: "center", padding: "32px 24px" }}>
        <div style={{ fontSize: 52, fontWeight: 900, color: passed ? C.trueGreen : C.red, lineHeight: 1 }}>{score}%</div>
        <div style={{ marginTop: 8, marginBottom: 4, fontSize: 16, fontWeight: 800, color: C.text }}>{quizName}</div>
        {subtitle && <div style={{ fontSize: 12, color: C.textMuted, marginBottom: 4 }}>{subtitle}</div>}
        <div style={{ fontSize: 13, color: C.textSub, marginBottom: 16 }}>
          {correctCount} of {gradedRows.length} correct{attempt?.date ? ` · ${attempt.date}` : ""}
        </div>
        <div style={{ display: "inline-flex", alignItems: "center", gap: 8, padding: "6px 16px", borderRadius: 99, background: passed ? "#DCFCE7" : "#FEE2E2", border: `1px solid ${passed ? "#86EFAC" : "#FCA5A5"}` }}>
          <span style={{ fontSize: 13, fontWeight: 800, color: passed ? "#166534" : "#991B1B" }}>{passed ? "Passed" : "Retry"}</span>
        </div>
        {points != null && points > 0 && (
          <div style={{ marginTop: 12, fontSize: 12, fontWeight: 700, color: C.orange }}>+{points} XP</div>
        )}
        {showRetake && onRetake && (
          <button onClick={onRetake} style={{ marginTop: 20, padding: "10px 24px", borderRadius: 10, border: `1px solid ${C.orange}`, background: C.orangeLight, color: C.orange, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
            Retake Quiz
          </button>
        )}
      </Card>

      {/* Honest degrade — no immutable record for this attempt (legacy, or an
          official pass whose quiz changed before a snapshot existed). Shown
          regardless of reveal so legacy learner reviews say so plainly. */}
      {unavailable && (
        <div style={{ padding: "12px 16px", borderRadius: 10, background: "#FFF7ED", border: `1px solid ${C.creamBorder}`, fontSize: 13, color: C.textSub }}>
          Exact historical answer detail unavailable for this attempt.
        </div>
      )}

      {/* Per-question breakdown */}
      <div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.textMuted, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 12 }}>Question Review</div>
        {reviewStatus === "loading" ? (
          <LoadingState rows={3} message="Loading your review…" />
        ) : reviewStatus === "error" ? (
          <ErrorState message="Your score is saved, but we couldn't load the detailed review. Please try again." onRetry={onRetryReview} />
        ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {rows.map((r, i) => {
            const isOpenQ  = r.type === "open";
            const isMatchQ = r.type === "match";
            const isKnownQ = ["mc", "tf", "type", "slider", "match", "open"].includes(r.type);
            const sol = r.solution; // canonical, only present when revealing
            const badgeBg   = (isOpenQ || r.isCorrect == null) ? C.muted   : r.isCorrect ? "#DCFCE7" : "#FEE2E2";
            const badgeColor= (isOpenQ || r.isCorrect == null) ? C.textSub : r.isCorrect ? "#166534" : "#991B1B";
            const hasAnswer = isMatchQ
              ? Array.isArray(r.selected) && r.selected.length > 0
              : (r.selected !== null && r.selected !== undefined && r.selected !== "");
            const badgeText = !isKnownQ ? "Unsupported"
              : isOpenQ ? (hasAnswer ? "Submitted" : "Skipped")
              : r.isCorrect == null ? "Submitted"
              : r.isCorrect ? "Correct" : "Incorrect";
            const borderColor = (isOpenQ || r.isCorrect == null) ? C.creamBorder : r.isCorrect ? C.trueGreen : C.red;
            const timeLabel = r.timeSpent != null ? `Answered in ${r.timeSpent}s` : null;

            // Submitted answer label (non-matching)
            let answerLabel = null;
            if (r.type === "mc" || r.type === "tf") answerLabel = optionLabel(r.options, r.selected);
            else if (r.type === "type" || r.type === "open") answerLabel = typeof r.selected === "string" ? r.selected : null;
            else if (r.type === "slider") answerLabel = (r.selected != null ? String(r.selected) : null);

            // Correct-answer label (reveal + snapshot only)
            let correctLabel = null;
            if (reveal && sol) {
              if (r.type === "mc" || r.type === "tf") correctLabel = optionLabel(sol.options, sol.correct);
              else if (r.type === "type") correctLabel = (sol.acceptedAnswers ?? []).join(", ") || null;
              else if (r.type === "slider") correctLabel = `${sol.correct ?? 5} ±${sol.tolerance ?? 1}`;
            }

            return (
              <Card key={r.questionId ?? i} style={{ borderLeft: `4px solid ${borderColor}` }}>
                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, marginBottom: 4 }}>
                  <p style={{ margin: 0, fontSize: 14, fontWeight: 600, color: C.text, lineHeight: 1.5 }}>{i + 1}. {r.text || `Question ${i + 1}`}</p>
                  <span style={{ fontSize: 12, fontWeight: 700, color: badgeColor, flexShrink: 0, padding: "2px 8px", borderRadius: 99, background: badgeBg }}>{badgeText}</span>
                </div>
                {timeLabel && <div style={{ fontSize: 11, color: C.textMuted, marginBottom: 8 }}>{timeLabel}</div>}

                {/* Matching — per-pair breakdown (labels from leftItems; correct only when revealing) */}
                {isMatchQ && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                    {(reveal && Array.isArray(sol?.pairs)
                      ? sol.pairs.map((pair, li) => {
                          const mp = (r.selected ?? []).find(m => m.leftIdx === li);
                          const pairOk = !!mp && mp.rightText === pair.right;
                          return (
                            <div key={li} style={{ fontSize: 13, color: pairOk ? "#166534" : "#991B1B" }}>
                              <strong>{pair.left}</strong> → {mp ? mp.rightText : <em style={{ color: C.textMuted }}>no match</em>}
                              {!pairOk && <span style={{ color: "#166534" }}> (correct: {pair.right})</span>}
                            </div>
                          );
                        })
                      : (r.selected ?? []).map((mp, li) => (
                          <div key={li} style={{ fontSize: 13, color: C.textSub }}>
                            <strong>{(r.leftItems ?? [])[mp.leftIdx] ?? `Prompt ${mp.leftIdx + 1}`}</strong> → {mp.rightText}
                          </div>
                        ))
                    )}
                  </div>
                )}

                {/* Submitted answer (non-matching) */}
                {!isMatchQ && hasAnswer && (
                  <div style={{ fontSize: 13, color: isOpenQ ? C.textSub : (r.isCorrect ? "#166534" : "#991B1B") }}>
                    <strong>Your answer:</strong> {answerLabel || <em style={{ color: C.textMuted }}>—</em>}
                  </div>
                )}
                {!isMatchQ && !hasAnswer && (
                  <div style={{ fontSize: 13, color: C.textMuted }}><em>No answer submitted.</em></div>
                )}

                {/* Correct answer — reveal + snapshot only, and only when the learner got it wrong */}
                {!isMatchQ && reveal && sol && r.isCorrect === false && correctLabel && (
                  <div style={{ fontSize: 13, color: "#166534", marginTop: 4 }}>
                    <strong>Correct answer:</strong> {correctLabel}
                  </div>
                )}

                {/* Explanation — reveal + snapshot only */}
                {reveal && sol?.explanation && (
                  <div style={{ marginTop: 8, padding: "10px 12px", borderRadius: 8, background: C.pageBg, border: `1px solid ${C.creamBorder}` }}>
                    <p style={{ margin: 0, fontSize: 12, color: C.textSub, lineHeight: 1.6 }}>{sol.explanation}</p>
                  </div>
                )}
              </Card>
            );
          })}
        </div>
        )}
      </div>
    </div>
  );
}

// ── QuizLibraryGrid ──────────────────────────────────────────────────────────
// Admin/Manager quiz list. Displays each quiz with edit, favorite, active-toggle,
// and — instead of a permanent delete — Archive (active quizzes) / Restore
// (archived quizzes). Archiving is soft and reversible (migration 065): it
// preserves every attempt/score/result and cancels the quiz's active assignments
// server-side. Archived quizzes render in a separate, dimmed section at the
// bottom and are never assignable/launchable until restored.
function QuizLibraryGrid({ quizzes, onEditQuiz, onNav, onArchiveQuiz, onRestoreQuiz, onToggleFavorite, onToggleActive, onAssign, onLaunchQuiz, canEdit = true, canDelete = true, canAssign = true, canLaunch = false, tagModelByQuiz = null, tagCatalogById = new Map() }) {
  const [confirmArchive, setConfirmArchive] = useState(null); // quiz id pending archive confirm

  const activeQuizzes   = quizzes.filter(q => q.status !== "archived");
  const archivedQuizzes = quizzes.filter(q => q.status === "archived");

  const renderRow = (quiz) => {
        const qCount   = quiz.questions?.length ?? 0;
        const archived = quiz.status === "archived";
        const inactive = quiz.status === "inactive";
        const fav      = !!quiz.favorite;
        return (
          <div key={quiz.id} style={{
            display: "flex", alignItems: "center", gap: 16,
            padding: "16px 20px", borderRadius: 14,
            border: `1.5px solid ${C.border}`, background: C.white,
            opacity: archived ? 0.6 : inactive ? 0.6 : 1, transition: "opacity 0.15s",
          }}>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{quiz.name}</span>
                {fav && !archived && <span style={{ fontSize: 11, color: C.orange }}>★</span>}
                {archived ? (
                  <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 7px", borderRadius: 4, background: C.muted, color: C.textMuted }}>Archived</span>
                ) : inactive && (
                  <span style={{ fontSize: 10, fontWeight: 700, padding: "2px 7px", borderRadius: 4, background: C.muted, color: C.textMuted }}>Inactive</span>
                )}
              </div>
              <div style={{ fontSize: 12, color: C.textSub, marginTop: 2 }}>
                {qCount} question{qCount !== 1 ? "s" : ""} · Created {quiz.createdAt}
                {quiz.track ? ` · ${quiz.track}` : ""}
              </div>
              {tagModelByQuiz && (
                <QuizTagChips model={quizTagModel(tagModelByQuiz, quiz.id)} catalogById={tagCatalogById} />
              )}
            </div>

            {/* Actions */}
            <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
              {archived ? (
                /* Archived quiz: only Restore. No assign/launch/edit/toggle — an
                   archived quiz is out of circulation until restored. Its
                   attempts/results remain accessible via drilldowns. */
                canDelete && (
                  <button
                    onClick={() => onRestoreQuiz?.(quiz.id)}
                    style={{ fontSize: 12, fontWeight: 700, padding: "6px 14px", borderRadius: 8, border: `1px solid ${C.orange}`, background: C.orangeLight, color: C.orange, cursor: "pointer" }}
                  >Restore</button>
                )
              ) : (
              <>
              {/* Favorite */}
              <button
                onClick={() => onToggleFavorite(quiz.id)}
                title={fav ? "Unfavorite" : "Favorite"}
                style={{ background: "none", border: "none", cursor: "pointer", fontSize: 16, color: fav ? C.orange : C.textMuted, padding: "4px 6px", borderRadius: 6 }}
              >{fav ? "★" : "☆"}</button>

              {/* Active toggle */}
              <button
                onClick={() => onToggleActive(quiz.id)}
                title={inactive ? "Set active" : "Set inactive"}
                style={{ fontSize: 11, fontWeight: 700, padding: "4px 10px", borderRadius: 6, border: `1px solid ${C.border}`, background: inactive ? C.muted : C.greenBg, color: inactive ? C.textMuted : C.trueGreen, cursor: "pointer" }}
              >{inactive ? "Inactive" : "Active"}</button>

              {/* Launch */}
              {canLaunch && onLaunchQuiz && (
                <button
                  onClick={() => onLaunchQuiz(quiz)}
                  title="Launch as live game"
                  style={{ fontSize: 12, fontWeight: 700, padding: "6px 14px", borderRadius: 8, border: "none", background: C.green, color: "#fff", cursor: "pointer" }}
                >▶ Launch</button>
              )}

              {/* Assign */}
              {canAssign && onAssign && (
                <button
                  onClick={() => onAssign(quiz)}
                  style={{ fontSize: 12, fontWeight: 700, padding: "6px 14px", borderRadius: 8, border: `1px solid ${C.orange}`, background: C.orangeLight, color: C.orange, cursor: "pointer" }}
                >Assign</button>
              )}

              {/* Edit */}
              {canEdit && (
                <button
                  onClick={() => { onEditQuiz(quiz); onNav("rankd-quiz-builder"); }}
                  style={{ fontSize: 12, fontWeight: 700, padding: "6px 14px", borderRadius: 8, border: `1px solid ${C.border}`, background: C.white, color: C.text, cursor: "pointer" }}
                >Edit</button>
              )}

              {/* Archive (replaces permanent Delete): soft + reversible, preserves
                  all attempts/results and cancels this quiz's active assignments. */}
              {canDelete && (confirmArchive === quiz.id ? (
                <div style={{ display: "flex", gap: 4 }}>
                  <button
                    onClick={() => { onArchiveQuiz?.(quiz.id); setConfirmArchive(null); }}
                    style={{ fontSize: 11, fontWeight: 700, padding: "5px 10px", borderRadius: 6, border: "none", background: C.orange, color: "#fff", cursor: "pointer" }}
                  >Archive</button>
                  <button
                    onClick={() => setConfirmArchive(null)}
                    style={{ fontSize: 11, fontWeight: 700, padding: "5px 10px", borderRadius: 6, border: `1px solid ${C.border}`, background: C.white, color: C.textSub, cursor: "pointer" }}
                  >Cancel</button>
                </div>
              ) : (
                <button
                  onClick={() => setConfirmArchive(quiz.id)}
                  title="Archive quiz"
                  style={{ fontSize: 12, fontWeight: 700, padding: "6px 14px", borderRadius: 8, border: `1px solid ${C.border}`, background: C.white, color: C.textSub, cursor: "pointer" }}
                >Archive</button>
              ))}
              </>
              )}
            </div>
          </div>
        );
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      {activeQuizzes.map(renderRow)}
      {archivedQuizzes.length > 0 && (
        <>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8 }}>
            <span style={{ fontSize: 12, fontWeight: 700, color: C.textMuted, letterSpacing: "0.04em" }}>ARCHIVED ({archivedQuizzes.length})</span>
            <div style={{ flex: 1, height: 1, background: C.border }} />
          </div>
          {archivedQuizzes.map(renderRow)}
        </>
      )}
    </div>
  );
}

// ── Manager Quiz Tracking ──────────────────────────────────────────────────────
// Expands quiz assignments (tenant_assignments, content_type = "quiz") into one
// row per assigned rep, joined against real quiz_attempts so status/score/attempt
// count always reflect the DB — never a locally-cached guess. Mirrors the
// assignedTo-resolution pattern used by LearnScreen's manager Assignments tab.
// Assignment Experience Priority 6 — label normalized from "Assigned" to
// "Not Started" so this specific engine status (`not_started`) reads
// identically here and in LearnScreen's unified tracking table /
// ContentAssignmentDrilldown's STATUS_CONFIG, which already used "Not
// Started" for the same status. The internal key stays "assigned" (it's
// wired into statusTab state/filters below) — only the displayed word
// changes. "Active" is left as-is elsewhere: it names a different,
// already-consistent concept (not_started + in_progress + overdue combined,
// see contentService.js's ASSIGNMENTS header), not this single status.
const QUIZ_STATUS_CONFIG = {
  assigned:    { label: "Not Started", bg: "#F1F5F9", text: "#475569" },
  in_progress: { label: "In Progress", bg: "#DBEAFE", text: "#1D4ED8" },
  completed:   { label: "Completed",   bg: "#DCFCE7", text: "#166534" },
  overdue:     { label: "Overdue",     bg: "#FEE2E2", text: "#991B1B" },
};

function resolveAssignedUsers(assignedTo, orgUsers) {
  if (!assignedTo) return [];
  if (assignedTo.type === "individual") {
    const u = orgUsers.find(u => u.id === assignedTo.userId);
    if (u) return [u];
    if (assignedTo.userName) return [{ id: assignedTo.userId ?? "__ind__", name: assignedTo.userName, initials: (assignedTo.userName[0] ?? "?").toUpperCase(), color: C.orange }];
    return [];
  }
  if (assignedTo.type === "group") {
    const users = orgUsers.filter(u => u.role !== "ralli_admin" && u.role !== "superadmin" && u.role !== "orgAdmin");
    return users.length ? users : [{ id: "__group__", name: "All users", initials: "ALL", color: C.blue, _isAggregate: true }];
  }
  if (assignedTo.type === "team") {
    const users = assignedTo.teamId ? orgUsers.filter(u => u.teamId === assignedTo.teamId) : [];
    return users.length ? users : [{ id: "__team__", name: assignedTo.teamName ?? "Team", initials: "T", color: C.purple, _isAggregate: true }];
  }
  return [];
}

// Expands quiz assignments into per-rep rows. Status/completedAt come from
// the shared Resolved Assignment engine (src/lib/assignmentEngine.js) —
// gated on THIS assignment row's own assigned_at, exactly like
// _quiz_assignment_active_user_ids() (036_assignment_aware_quiz_eligibility.sql)
// enforces server-side. attemptCount/latestScore intentionally stay
// ungated — they're a full attempt-history display, not a resolution check.
function buildQuizAssignmentRows(assignments, attempts, quizzes, orgUsers) {
  // ONE primary row per (user, quiz), resolved against the LATEST assignment
  // instance via the shared engine helper. A quiz reassigned N times to the
  // same rep is a single row (not N), and every column is scoped to the latest
  // assignment's window — never a lifetime value masquerading as the current
  // assignment. Older instances and the FULL attempt history are preserved on
  // the row (older / allAttempts) for the drill-down.
  const byUserQuiz = new Map();
  for (const a of assignments) {
    const quiz = quizzes.find(q => q.id === a.contentId);
    if (!quiz) continue;
    const users = resolveAssignedUsers(a.assignedTo, orgUsers);
    for (const u of users) {
      const key = `${u.id}::${a.contentId}`;
      if (!byUserQuiz.has(key)) byUserQuiz.set(key, { quiz, user: u, rows: [] });
      byUserQuiz.get(key).rows.push(a);
    }
  }

  return [...byUserQuiz.values()].map(({ quiz, user, rows }) => {
    const allAttempts = user._isAggregate ? [] : attempts
      .filter(at => at.quiz_id === quiz.id && at.user_id === user.id)
      .slice()
      .sort((x, y) => new Date(y.created_at) - new Date(x.created_at)); // newest first — full history

    // Shared reduction: latest assignment + status + metrics scoped to it.
    const r = resolveLatestQuizAssignment(rows, allAttempts);
    const latest = r.latest ?? rows[0];
    // QUIZ_STATUS_CONFIG's internal key for the not-yet-started state is
    // still "assigned" (wired into the status filter below); its displayed
    // label is "Not Started", matching the engine's "not_started" vocabulary.
    const status = r.status === "not_started" ? "assigned" : r.status;

    return {
      key: `${latest?.id}-${user.id}`,
      assignment: latest, quiz, user,
      attempts: r.scopedAttempts,        // scoped to latest assignment — powers Attempts column
      allAttempts,                        // full lifetime history — powers the drill-down
      olderAssignments: r.older ?? [],    // prior assignment instances (history)
      attemptCount: r.attemptCount, latestScore: r.latestScore, bestScore: r.bestScore,
      status, progress: r.progress, completedAt: r.completedAt,
    };
  });
}

// Read-only breakdown of every attempt a rep has made on one quiz — score,
// completion date, and per-question submission vs. the IMMUTABLE historical
// answer key. The answer key comes ONLY from each attempt's solution snapshot
// (quiz_attempt_solutions), never the quiz's current mutable questions, so a
// quiz edited after the attempt can't rewrite what the rep was graded against.
// Trusted (server_v2) attempts have a snapshot; legacy attempts don't and
// degrade honestly ("Exact historical answer detail unavailable").
function QuizAttemptDrilldown({ row, onBack }) {
  const { quiz, user } = row;
  // Drill-down shows the FULL lifetime attempt history (across every
  // reassignment), not just the latest-assignment window the table scopes to.
  const attempts = row.allAttempts ?? row.attempts ?? [];
  const [openId, setOpenId] = useState(attempts[0]?.id ?? null);
  const [snapshots, setSnapshots] = useState(null); // { attemptId: solution[] } | null (loading)

  useEffect(() => {
    let alive = true;
    const ids = attempts.map(a => a.id).filter(Boolean);
    if (ids.length === 0) { setSnapshots({}); return; }
    getAttemptSolutions(ids)
      .then(({ data }) => { if (alive) setSnapshots(data ?? {}); })
      .catch(() => { if (alive) setSnapshots({}); });
    return () => { alive = false; };
  }, [row.key]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: C.textSub, fontSize: 13, fontWeight: 700, padding: 0 }}>← All Assignments</button>
      </div>
      <div style={{ padding: "14px 18px", borderRadius: 12, background: C.white, border: `1px solid ${C.border}`, display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 34, height: 34, borderRadius: "50%", background: user.color ?? C.orange, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, color: "#fff", flexShrink: 0 }}>
          {(user.initials ?? user.name?.[0] ?? "?").toUpperCase()}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{user.name}</div>
          <div style={{ fontSize: 12, color: C.textSub }}>{quiz.title ?? quiz.name} · {attempts.length} attempt{attempts.length !== 1 ? "s" : ""}</div>
        </div>
      </div>

      {attempts.length === 0 ? (
        <div style={{ padding: 40, textAlign: "center", color: C.textMuted, fontSize: 14 }}>No attempts recorded yet.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {attempts.map((at, i) => {
            const isOpen = openId === at.id;
            const dateLabel = (() => { try { return new Date(at.created_at).toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" }); } catch { return at.created_at; } })();
            return (
              <div key={at.id ?? i} style={{ border: `1px solid ${C.border}`, borderRadius: 12, background: C.white, overflow: "hidden" }}>
                <button onClick={() => setOpenId(isOpen ? null : at.id)} style={{
                  width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "14px 18px", background: "none", border: "none", cursor: "pointer", textAlign: "left",
                }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <span style={{ fontSize: 13, fontWeight: 700, color: C.text }}>Attempt {at.attempt_num ?? attempts.length - i}</span>
                    <span style={{ fontSize: 12, color: C.textSub }}>{dateLabel}</span>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <span style={{ fontSize: 13, fontWeight: 800, color: at.passed ? C.trueGreen : C.red }}>{at.score}%</span>
                    <span style={{ fontSize: 11, fontWeight: 700, padding: "2px 8px", borderRadius: 99, background: at.passed ? "#DCFCE7" : "#FEE2E2", color: at.passed ? "#166534" : "#991B1B" }}>{at.passed ? "Passed" : "Not passed"}</span>
                    <span style={{ fontSize: 12, color: C.textMuted }}>{isOpen ? "▲" : "▼"}</span>
                  </div>
                </button>
                {isOpen && (
                  <div style={{ padding: "0 18px 18px", borderTop: `1px solid ${C.creamBorder}` }}>
                    {snapshots === null ? (
                      <LoadingState rows={2} message="Loading attempt detail…" />
                    ) : (() => {
                      const mar = buildManagerAttemptReview(at, snapshots[String(at.id)]);
                      return (
                        <SnapshotQuizReview
                          quizName={quiz.title ?? quiz.name}
                          attempt={{ score: at.score, passed: at.passed, date: dateLabel }}
                          rows={reviewRows({ answers: mar.answers, solution: mar.solution, reveal: mar.reveal })}
                          reveal={mar.reveal}
                          unavailable={mar.unavailable}
                          showRetake={false}
                          showBack={false}
                        />
                      );
                    })()}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// Read-only detail view for one rep's lesson or course assignment — the
// lesson/course counterpart to QuizAttemptDrilldown above, giving managers
// the same "open a row, see the relevant history" experience for every
// content type (Task 11). Lessons/courses have no per-attempt history the
// way quizzes do (lesson_completions is a single upsert row, not a log), so
// there's no fake attempt list here — just the assignment's own metadata
// plus, for courses, a per-lesson completion breakdown (reusing the same
// engine-computed data the tracking table already has).
function ContentAssignmentDrilldown({ row, onBack }) {
  const { a, content, isCourse, u: user, status, progress, completedAt, courseLessons = [], completedAtByLesson } = row;
  const STATUS_CONFIG = {
    not_started: { label: "Not Started", bg: C.muted,   text: C.textSub },
    in_progress: { label: "In Progress", bg: C.blueBg,  text: C.blue    },
    completed:   { label: "Completed",   bg: C.greenBg, text: C.green   },
    overdue:     { label: "Overdue",     bg: C.redBg,   text: C.red     },
  };
  const sc = STATUS_CONFIG[status] ?? STATUS_CONFIG.not_started;
  const fmt = (iso) => { try { return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); } catch { return "—"; } };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: C.textSub, fontSize: 13, fontWeight: 700, padding: 0 }}>← All Assignments</button>
      </div>
      <div style={{ padding: "14px 18px", borderRadius: 12, background: C.white, border: `1px solid ${C.border}`, display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ width: 34, height: 34, borderRadius: "50%", background: user.color ?? C.orange, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, color: "#fff", flexShrink: 0 }}>
          {(user.initials ?? user.name?.[0] ?? "?").toUpperCase()}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{user.name}</div>
          <div style={{ fontSize: 12, color: C.textSub }}>{content.title ?? content.name}{isCourse ? ` · ${courseLessons.length} lesson${courseLessons.length !== 1 ? "s" : ""}` : ""}</div>
        </div>
        <span style={{ fontSize: 11, fontWeight: 700, padding: "3px 8px", borderRadius: 6, background: sc.bg, color: sc.text, flexShrink: 0 }}>{sc.label}</span>
      </div>

      {/* Assignment metadata — same fields every content type shows in the tracking table */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 10 }}>
        {[
          { label: "Assigned",  value: a.assignedAt ?? "—" },
          { label: "Due",       value: a.dueAt && a.dueAt !== "Open" ? fmt(a.dueAt) : "Open" },
          { label: "Required",  value: a.required ? "Required" : "Recommended" },
          { label: "Completed", value: completedAt ? fmt(completedAt) : "—" },
        ].map(({ label, value }) => (
          <div key={label} style={{ padding: "10px 14px", background: C.pageBg, borderRadius: 10 }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: C.textMuted, letterSpacing: "0.05em", marginBottom: 3 }}>{label.toUpperCase()}</div>
            <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{value}</div>
          </div>
        ))}
      </div>

      {!isCourse ? (
        // Lesson — nothing more to drill into beyond its own completion state,
        // already shown above. No attempt/score fields: lessons don't have them.
        <div style={{ padding: "12px 14px", background: C.pageBg, borderRadius: 10, fontSize: 13, color: C.textSub }}>
          {status === "completed" ? "This lesson is complete." : "This lesson has not been completed yet."}
        </div>
      ) : (
        // Course — per-lesson breakdown, so a manager can see exactly which
        // lessons are blocking completion, same "progress" data the table's
        // percentage is built from.
        (() => {
        // Durable "Next lesson" + remaining, derived only from persisted
        // completions gated on THIS instance's assigned_at (same rule as the
        // rows below). Honest by construction: it's the first course member
        // with no qualifying completion — never a "current lesson" / live
        // position, which we do not persist (see durable-data audit).
        const isDone = (l) => {
          const lc = completedAtByLesson?.get(l.id);
          return !!lc && (!a.assignedAtRaw || new Date(lc) >= new Date(a.assignedAtRaw));
        };
        const nextLesson = status === "completed" ? null : courseLessons.find(l => !isDone(l)) ?? null;
        const remaining  = courseLessons.filter(l => !isDone(l)).length;
        return (
        <div>
          <div style={{ fontWeight: 700, fontSize: 13, color: C.text, marginBottom: 10 }}>Lesson Breakdown ({progress}% complete)</div>
          {status !== "completed" && courseLessons.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 12, fontSize: 12 }}>
              <span style={{ padding: "6px 12px", background: C.orangeLight, border: `1px solid ${C.orange}30`, borderRadius: 8, color: C.text }}>
                <strong style={{ color: C.orange }}>Next lesson:</strong> {nextLesson ? nextLesson.title : "—"}
              </span>
              <span style={{ padding: "6px 12px", background: C.pageBg, borderRadius: 8, color: C.textSub }}>
                {remaining} of {courseLessons.length} lesson{courseLessons.length !== 1 ? "s" : ""} remaining
              </span>
            </div>
          )}
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {courseLessons.map(l => {
              const lc = completedAtByLesson?.get(l.id);
              const done = !!lc && (!a.assignedAtRaw || new Date(lc) >= new Date(a.assignedAtRaw));
              return (
                <div key={l.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 14px", background: C.pageBg, borderRadius: 10 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{l.title}</div>
                  <span style={{ fontSize: 11, fontWeight: 700, padding: "2px 8px", borderRadius: 99, background: done ? C.greenBg : C.muted, color: done ? C.green : C.textSub }}>
                    {done ? `Complete · ${fmt(lc)}` : "Incomplete"}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
        );
        })()
      )}
    </div>
  );
}

// Manager/admin quiz tracking panel — Assigned / In Progress / Completed / Overdue /
// Drafts / All. Loads assignments + quiz_attempts fresh from Supabase on mount and
// whenever refreshKey changes (bumped after a new assignment is created), so status
// is always correct immediately after submission and after a page refresh.
function QuizTrackingPanel({ quizzes, orgUsers, tenantId, isReal, refreshKey, onAssign, canAssign }) {
  const [assignments, setAssignments] = useState([]);
  const [attempts,    setAttempts]    = useState([]);
  const [loading,     setLoading]     = useState(isReal);
  const [loadError,   setLoadError]   = useState(null); // Task 8 — manager tracking data
  const [statusTab,   setStatusTab]   = useState("all"); // Assignments opens on All
  const [assigneeFilter, setAssigneeFilter] = useState("all");
  const [search,      setSearch]      = useState("");
  const [selectedKey, setSelectedKey] = useState(null); // row.key of drilled-in assignment

  const loadTracking = useCallback(() => {
    if (!isReal || !tenantId) { setLoading(false); return; }
    setLoading(true);
    setLoadError(null);
    Promise.all([
      getTenantAssignments(tenantId),
      getTenantQuizAttempts(tenantId),
    ]).then(([{ data: dbAssignments }, { data: dbAttempts }]) => {
      if (!dbAssignments || !dbAttempts) {
        setLoadError("Could not load quiz assignment tracking. Please try again.");
        setLoading(false);
        return;
      }
      setAssignments(dbAssignments.filter(a => a.contentType === "quiz"));
      setAttempts(dbAttempts);
      setLoading(false);
    }).catch(() => {
      setLoadError("Could not load quiz assignment tracking. Please try again.");
      setLoading(false);
    });
  }, [tenantId, isReal]);

  useEffect(() => { loadTracking(); }, [loadTracking, refreshKey]);

  // Task 12 — live updates. Managers watching this tracking panel see a
  // teammate's assignment appear/change/disappear without a manual refresh,
  // whether it came from this browser tab (already covered by the
  // refreshKey bump after AssignContentModal submits) or from someone else
  // entirely. Re-runs the same retryable loadTracking(). Tenant-scoped;
  // cleaned up on unmount/tenant change.
  useEffect(() => {
    if (!isReal || !tenantId) return;
    return subscribeToTenantAssignments(tenantId, "quizzes-tracking", () => loadTracking());
  }, [isReal, tenantId, loadTracking]);

  const allRows = buildQuizAssignmentRows(assignments, attempts, quizzes, orgUsers);
  const draftQuizzes = quizzes.filter(q => !assignments.some(a => a.contentId === q.id));

  const sq = search.trim().toLowerCase();
  const searchedRows = sq
    ? allRows.filter(r => (r.quiz.title ?? r.quiz.name ?? "").toLowerCase().includes(sq) || r.user.name?.toLowerCase().includes(sq))
    : allRows;
  const searchedDrafts = sq
    ? draftQuizzes.filter(q => (q.title ?? q.name ?? "").toLowerCase().includes(sq))
    : draftQuizzes;

  const counts = {
    assigned:    allRows.filter(r => r.status === "assigned").length,
    in_progress: allRows.filter(r => r.status === "in_progress").length,
    completed:   allRows.filter(r => r.status === "completed").length,
    overdue:     allRows.filter(r => r.status === "overdue").length,
    drafts:      draftQuizzes.length,
    all:         allRows.length + draftQuizzes.length,
  };

  const selectedRow = selectedKey ? allRows.find(r => r.key === selectedKey) : null;
  if (selectedRow) {
    return <QuizAttemptDrilldown row={selectedRow} onBack={() => setSelectedKey(null)} />;
  }

  if (!isReal) {
    return (
      <div style={{ padding: 48, textAlign: "center", background: C.white, borderRadius: 16, border: `1px solid ${C.border}` }}>
        <p style={{ fontSize: 15, fontWeight: 700, color: C.text, margin: "0 0 4px" }}>Tracking is available for connected accounts</p>
        <p style={{ fontSize: 13, color: C.textSub, margin: 0 }}>Demo mode doesn't persist quiz assignments or attempts — sign in with a real account to see live tracking.</p>
      </div>
    );
  }

  if (loading) return <LoadingState rows={3} message="Loading quiz assignments…" />;

  if (loadError) return <ErrorState message={loadError} onRetry={loadTracking} />;

  const assigneeFiltered = assigneeFilter === "all" ? searchedRows : searchedRows.filter(r => r.user.id === assigneeFilter);
  const rowsForStatusTab = statusTab === "all" ? assigneeFiltered : assigneeFiltered.filter(r => r.status === statusTab);
  // Drafts (never-assigned quizzes) show only in the unfiltered All view.
  const draftsToShow = (statusTab === "all" && assigneeFilter === "all") ? searchedDrafts : [];
  // Assignee options come from the actual rows (real reps only).
  const assigneeOptions = [...new Map(allRows.map(r => [r.user.id, r.user])).values()]
    .filter(u => u && !u._isAggregate && u.id)
    .sort((a, b) => (a.name ?? "").localeCompare(b.name ?? ""));

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {/* Search */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 14px", borderRadius: 10, background: C.cardBg, border: `1px solid ${C.creamBorder}`, maxWidth: 320 }}>
        <span style={{ fontSize: 13, color: C.textMuted, flexShrink: 0 }}>Search</span>
        <input
          type="text" value={search} placeholder="Quiz or rep name…"
          onChange={e => setSearch(e.target.value)}
          style={{ flex: 1, border: "none", background: "transparent", fontSize: 13, color: C.text, outline: "none", fontFamily: "inherit" }}
        />
        {search && <button onClick={() => setSearch("")} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 12, color: C.textMuted, padding: 0 }}>✕</button>}
      </div>

      {/* Filters — one Status dropdown (exactly the 5 states) + an Assignee dropdown */}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: C.textSub, fontWeight: 600 }}>
          Status
          <select value={statusTab} onChange={e => setStatusTab(e.target.value)} style={{
            padding: "7px 12px", borderRadius: 8, border: `1px solid ${C.border}`, background: C.white,
            color: C.text, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit",
          }}>
            <option value="all">All ({counts.all})</option>
            <option value="assigned">Not Started ({counts.assigned})</option>
            <option value="in_progress">In Progress ({counts.in_progress})</option>
            <option value="completed">Completed ({counts.completed})</option>
            <option value="overdue">Overdue ({counts.overdue})</option>
          </select>
        </label>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: C.textSub, fontWeight: 600 }}>
          Assignee
          <select value={assigneeFilter} onChange={e => setAssigneeFilter(e.target.value)} style={{
            padding: "7px 12px", borderRadius: 8, border: `1px solid ${C.border}`, background: C.white,
            color: C.text, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit", maxWidth: 220,
          }}>
            <option value="all">All assignees</option>
            {assigneeOptions.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
          </select>
        </label>
      </div>

      {/* Assignment rows table */}
      {rowsForStatusTab.length > 0 && (
        <div style={{ borderRadius: 12, overflow: "hidden", border: `1px solid ${C.border}` }}>
          <div style={{ overflowX: "auto", WebkitOverflowScrolling: "touch" }}>
            {/* Column set matches the shared tracking baseline (Task 11): user,
                content, status, assigned/due, required, progress, completion
                date — plus quiz-only latest/best score and attempts. */}
            <div style={{ minWidth: 980, display: "grid", gridTemplateColumns: "1.8fr 1.2fr 0.75fr 0.75fr 0.85fr 0.8fr 1fr 0.6fr 0.85fr", gap: 10, padding: "10px 16px", background: C.pageBg, fontSize: 11, fontWeight: 700, color: C.textMuted, letterSpacing: "0.05em" }}>
              <span>QUIZ</span><span>REP / TEAM</span><span>ASSIGNED</span><span>DUE</span>
              <span title="Resolved state of the latest assignment: Not Started, In Progress (attempted, not passed), Completed (passed), or Overdue (past due, not passed).">STATUS</span>
              <span title="Binary for this assignment: 0% until the quiz is passed, 100% once passed. Quizzes have no partial progress.">PROGRESS</span>
              <span title="Latest and best score from attempts made after this assignment's assigned date.">SCORE</span>
              <span title="Number of attempts made after this assignment's assigned date.">ATTEMPTS</span>
              <span title="Date of the first passing attempt after this assignment's assigned date.">DONE</span>
            </div>
            {rowsForStatusTab.map(row => {
              const sc = QUIZ_STATUS_CONFIG[row.status];
              const assignedLabel = row.assignment.assignedAt ?? "—";
              const dueLabel = row.assignment.dueAt && row.assignment.dueAt !== "Open"
                ? (() => { try { return new Date(row.assignment.dueAt).toLocaleDateString("en-US", { month: "short", day: "numeric" }); } catch { return row.assignment.dueAt; } })()
                : "Open";
              const completedLabel = row.completedAt
                ? (() => { try { return new Date(row.completedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" }); } catch { return "—"; } })()
                : "—";
              // Drilldown is available whenever a rep has at least one
              // attempt on record — not gated to "completed" status, since a
              // failed-but-attempted quiz is exactly where a manager most
              // needs to see the question-by-question breakdown (Self-Paced
              // Quiz audit: Manager Review — no ambiguity).
              // Clickable whenever there's ANY attempt on record (full lifetime
              // history), so a fresh reassignment row still opens the drill-down
              // showing prior instances' attempts — not just this window's.
              const isClickable = (row.allAttempts?.length ?? row.attemptCount) > 0;
              return (
                <div key={row.key} style={{ minWidth: 980, display: "grid", gridTemplateColumns: "1.8fr 1.2fr 0.75fr 0.75fr 0.85fr 0.8fr 1fr 0.6fr 0.85fr", gap: 10, padding: "13px 16px", background: C.white, borderTop: `1px solid ${C.border}`, alignItems: "center" }}>
                  <div style={{ minWidth: 0 }}>
                    {isClickable ? (
                      <button onClick={() => setSelectedKey(row.key)} style={{ background: "none", border: "none", padding: 0, cursor: "pointer", textAlign: "left" }}>
                        <span style={{ fontSize: 13, fontWeight: 700, color: C.text, textDecoration: "underline", textDecorationColor: C.border }}>{row.quiz.title ?? row.quiz.name}</span>
                      </button>
                    ) : (
                      <span style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{row.quiz.title ?? row.quiz.name}</span>
                    )}
                    <div style={{ fontSize: 11, color: C.textSub }}>{row.assignment.required ? "Required" : "Recommended"}</div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 7, minWidth: 0 }}>
                    <div style={{ width: 22, height: 22, borderRadius: "50%", background: row.user.color ?? C.orange, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, fontWeight: 700, color: "#fff", flexShrink: 0 }}>
                      {(row.user.initials ?? row.user.name?.[0] ?? "?").toUpperCase()}
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 600, color: C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{row.user.name}</span>
                  </div>
                  <span style={{ fontSize: 12, color: C.textSub }}>{assignedLabel}</span>
                  <span style={{ fontSize: 12, color: row.status === "overdue" ? C.red : C.textSub, fontWeight: row.status === "overdue" ? 700 : 400 }}>{dueLabel}</span>
                  <div><span style={{ fontSize: 11, fontWeight: 700, padding: "3px 8px", borderRadius: 6, background: sc.bg, color: sc.text }}>{sc.label}</span></div>
                  <span style={{ fontSize: 12, color: C.textSub }}>{row.progress}%</span>
                  <div style={{ fontSize: 11, color: C.textSub, lineHeight: 1.4 }}>
                    {row.latestScore != null ? (
                      <>
                        <div style={{ fontSize: 12, fontWeight: 700, color: C.text }}>Latest {row.latestScore}%</div>
                        <div>Best {row.bestScore}%</div>
                      </>
                    ) : "—"}
                  </div>
                  <span style={{ fontSize: 12, color: C.textSub }}>{row.attemptCount}</span>
                  <span style={{ fontSize: 12, color: C.textSub }}>{completedLabel}</span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Draft quizzes — templates never assigned to anyone */}
      {draftsToShow.length > 0 && (
        <div>
          {statusTab === "all" && <h3 style={{ margin: "8px 0 10px", fontSize: 12, fontWeight: 800, color: C.textMuted, letterSpacing: "0.06em" }}>DRAFTS — NOT YET ASSIGNED ({draftsToShow.length})</h3>}
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {draftsToShow.map(q => (
              <div key={q.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 16px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.white }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{q.title ?? q.name}</div>
                  <div style={{ fontSize: 11, color: C.textSub }}>{q.questions?.length ?? 0} questions · Never assigned</div>
                </div>
                {canAssign && (
                  <button onClick={() => onAssign(q)} style={{ padding: "6px 14px", borderRadius: 8, border: `1px solid ${C.orange}`, background: C.orangeLight, color: C.orange, fontSize: 12, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>Assign</button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {rowsForStatusTab.length === 0 && draftsToShow.length === 0 && (
        <div style={{ padding: 48, textAlign: "center", background: C.white, borderRadius: 16, border: `1px solid ${C.border}` }}>
          <p style={{ fontSize: 15, fontWeight: 700, color: C.text, margin: "0 0 4px" }}>
            {search ? `No results for "${search}"` : "Nothing here yet"}
          </p>
          <p style={{ fontSize: 13, color: C.textSub, margin: 0 }}>
            {search ? "Try a different search term." : statusTab === "drafts" ? "Every quiz in your library has been assigned." : "Assign a quiz from the Library tab to start tracking results."}
          </p>
        </div>
      )}
    </div>
  );
}

// ── QuizzesScreen (user branch rewritten, admin branch preserved) ─────────────
function QuizzesScreen({ role, onNav, quizzes, onEditQuiz, onDeleteQuiz, onArchiveQuiz, onRestoreQuiz, onToggleFavorite, onToggleActive, pendingQuizId, onClearPendingQuiz, canCreate = true, canEdit = true, canDelete = true, canLaunch = true, canAssign = true, onAssignQuiz, onLaunchQuiz, orgUsers = [], orgs = [], currentUser = null, tenantId = null, isReal = false, quizzesReady = false, sharedAssignmentData = null, onRefreshQuizzes = null, onExitQuiz = null, pendingQuizReview = null }) {

  // ── USER VIEW ─────────────────────────────────────────────────────────────
  if (role === "user") {
    // Task 13 — assignments and attempt history now come from the shared
    // hook (owned once in App(), see useSharedUserAssignmentData) for real
    // users, instead of QuizzesScreen fetching/subscribing to them itself.
    // Demo mode is untouched — it keeps its own local seed state below,
    // exactly as before, since it never talked to Supabase for this data.
    const [demoAssignments, setDemoAssignments] = useState(USER_QUIZ_ASSIGNMENTS_SEED);

    // Merge shared assignments (filtered to "mine", same filter every other
    // consumer of this shared data already applies) with the quizzes prop
    // (which carries questions) — same merge loadUserQuizData used to do,
    // now derived instead of fetched+stored. quiz.attempts stays [] for real
    // users — userQuizAttempts (below) is the real source; see its comment.
    const realAssignments = useMemo(() => {
      if (!isReal || !currentUser) return [];
      const userTeamId = currentUser.teamId ?? null;
      const mine = (sharedAssignmentData?.assignments ?? []).filter(a =>
        a.contentType === "quiz" && (
          (a.assignedTo.type === "group"      && a.assignedTo.orgId === currentUser.orgId)  ||
          (a.assignedTo.type === "individual" && a.assignedTo.userId === currentUser.id)    ||
          (a.assignedTo.type === "team"       && userTeamId && userTeamId === a.assignedTo.teamId)
        )
      );
      // One card per quiz: dedupe assignment rows to the LATEST per quiz and
      // resolve its status through the shared engine helper — a prior pass no
      // longer hides a later reassignment, and a failed current assignment is
      // one Retry, never a second card.
      const rowsByContent = new Map();
      for (const a of mine) {
        if (!rowsByContent.has(a.contentId)) rowsByContent.set(a.contentId, []);
        rowsByContent.get(a.contentId).push(a);
      }
      const out = [];
      for (const [contentId, rows] of rowsByContent) {
        const quiz = quizzes.find(q => q.id === contentId);
        if (!quiz) continue;
        const attemptsForQuiz = (sharedAssignmentData?.quizAttempts ?? []).filter(at => at.quiz_id === contentId);
        const r = resolveLatestQuizAssignment(rows, attemptsForQuiz);
        const a = r.latest;
        out.push({
          ...quiz,
          id:             quiz.id,
          title:          quiz.name,
          dueAt:          a.dueAt === "Open" ? null : a.dueAt,
          assignedAt:     a.assignedAt,
          required:       a.required,
          attempts:       [],
          resolvedStatus: r.status,                 // not_started | in_progress | completed | overdue
          isComplete:     r.status === "completed", // canonical, instance-aware (latest assignment)
          scopedAttempts: r.scopedAttempts,         // attempts AFTER the latest assignment (newest first)
        });
      }
      return out;
    }, [isReal, currentUser, sharedAssignmentData?.assignments, sharedAssignmentData?.quizAttempts, quizzes]);

    // Attempt history keyed by quiz_id — source of truth for retake detection.
    // For real users, comes from userQuizAttempts (DB-backed, shared).
    // quiz.attempts is always [] for real users — only used as demo fallback.
    const realUserQuizAttempts = useMemo(() => {
      const byQuiz = {};
      for (const at of sharedAssignmentData?.quizAttempts ?? []) {
        if (!byQuiz[at.quiz_id]) byQuiz[at.quiz_id] = [];
        byQuiz[at.quiz_id].push(at);
      }
      return byQuiz;
    }, [sharedAssignmentData?.quizAttempts]);

    const assignments      = isReal ? realAssignments      : demoAssignments;
    const userQuizAttempts = isReal ? realUserQuizAttempts : {};
    // quizzesReady gates the merge above (needs the full quizzes array); demo
    // is always "loaded". Mirrors the old loadUserQuizData's readiness gate.
    const assignmentsLoaded = isReal ? (quizzesReady && !(sharedAssignmentData?.loading ?? false)) : true;
    const quizDataError     = isReal ? (sharedAssignmentData?.error ?? null) : null;
    const loadUserQuizData  = useCallback(() => { sharedAssignmentData?.retry?.(); }, [sharedAssignmentData?.retry]);

    // view: "list" | "starting" | "start_error" | "taking" | "submitting" | "results"
    const [view,         setView]         = useState("list");
    const [activeId,     setActiveId]     = useState(null);
    const [activeAttempt,setActiveAttempt]= useState(null); // demo results only
    const [tab,          setTab]          = useState("todo");
    const [search,       setSearch]       = useState("");
    // Learner-safe taking: `takeQuiz` is the SANITIZED quiz (get_quiz_for_attempt)
    // for real users, or the canonical demo seed for demo users — never the
    // App-level catalog (which for learners carries no question bodies at all).
    const [takeQuiz,     setTakeQuiz]     = useState(null);
    // Server-authoritative results/review model (SnapshotQuizReview) for real users.
    const [reviewModel,  setReviewModel]  = useState(null);
    // The attempt currently being reviewed (for a retryable review reload). Kept
    // separate from the taking flow so a review failure never starts a quiz.
    const [reviewTarget, setReviewTarget] = useState(null);
    const submittingRef = useRef(false);   // hard guard against a double submission

    const activeQuiz = assignments.find(q => q.id === activeId); // catalog card (metadata)

    const toast = useToast();

    // Load a quiz for taking. Real users fetch the SANITIZED quiz on demand
    // (Start AND Retake both refetch, so a mid-flight edit / new revision is
    // always picked up — no hard refresh). An RPC failure shows a Retry state,
    // and NEVER falls back to canonical quiz data. Demo uses the local seed.
    const beginQuiz = (id) => {
      setActiveId(id);
      setActiveAttempt(null);
      setReviewModel(null);
      if (!isReal) {
        setTakeQuiz(assignments.find(q => q.id === id) ?? null);
        setView("taking");
        return;
      }
      setTakeQuiz(null);
      setView("starting");
      getQuizForAttempt(id)
        .then(({ data, error }) => {
          if (error || !data) { setView("start_error"); return; }
          setTakeQuiz(rpcQuizToTakeable(data));
          setView("taking");
        })
        .catch(() => setView("start_error"));
    };
    const startQuiz  = (id) => beginQuiz(id);
    const retakeQuiz = (id) => beginQuiz(id);

    const fmtDate = (iso) => { try { return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); } catch { return ""; } };

    // Load the pass-gated per-question review for an attempt AFTER its score is
    // already accepted/shown. On failure it flips reviewStatus to 'error' (a
    // retryable review-loading error) — it NEVER resubmits and NEVER fabricates
    // answer detail; the server score/pass stays visible throughout.
    const loadReview = (attemptId) => {
      setReviewModel(m => (m ? { ...m, status: "loading" } : m));
      getQuizReview(activeId)
        .then(({ data, error }) => {
          if (error) { setReviewModel(m => (m ? { ...m, status: "error" } : m)); return; }
          const ar = buildAttemptReview(data, attemptId);
          setReviewModel(m => (m ? {
            ...m,
            status:      "ready",
            rows:        reviewRows({ answers: ar?.answers ?? m.fallbackAnswers ?? [], solution: ar?.solution ?? null, labelQuestions: takeQuiz?.questions ?? null, reveal: ar?.reveal ?? false }),
            reveal:      ar?.reveal ?? false,
            unavailable: ar?.unavailable ?? false,
          } : m));
        })
        .catch(() => setReviewModel(m => (m ? { ...m, status: "error" } : m)));
    };

    // Review a past attempt. Real users go through get_quiz_review, so the answer
    // key is revealed ONLY for an official pass and ONLY from the immutable
    // snapshot — never the current mutable quiz. The SANITIZED current questions
    // (get_quiz_for_attempt, NO answer keys) are fetched only to LABEL a trusted
    // attempt's rows (real prompt/type/options) so a failed review isn't blank;
    // legacy attempts get no labels and degrade honestly. This review flow has
    // its OWN loading/error states with a Back action and NEVER starts/opens the
    // quiz (the taking-flow "start_error" Retry, which begins the quiz, is not
    // reused here).
    const viewResults = (id, attempt) => {
      setActiveId(id);
      if (!isReal) {
        setTakeQuiz(assignments.find(q => q.id === id) ?? null);
        setActiveAttempt(attempt);
        setReviewModel(null);
        setView("results");
        return;
      }
      setReviewTarget({ id, attempt });
      setReviewModel(null);
      setView("review_loading");
      Promise.allSettled([getQuizReview(id), getQuizForAttempt(id)])
        .then(([revRes, quizRes]) => {
          const review = revRes.status === "fulfilled" ? revRes.value : { data: null, error: revRes.reason };
          if (review.error || !review.data) { setView("review_error"); return; }
          const sanitized = (quizRes.status === "fulfilled" && !quizRes.value.error && quizRes.value.data)
            ? (rpcQuizToTakeable(quizRes.value.data)?.questions ?? null) : null;
          const m = buildLearnerReviewModel({ reviewData: review.data, attemptId: attempt?.id, sanitizedQuestions: sanitized });
          if (!m) { setView("review_error"); return; }
          setReviewModel({
            attempt:     { score: m.score, passed: m.passed, date: fmtDate(m.createdAt) },
            rows:        m.rows,
            reveal:      m.reveal,
            unavailable: m.unavailable,
            points:      null,
            status:      "ready",
            attemptId:   m.attemptId,
          });
          setView("results");
        })
        .catch(() => setView("review_error"));
    };

    // Deep-link: open a specific quiz navigated here from HomeScreen.
    // For real users, assignments arrive async — hold until assignmentsLoaded is true
    // before resolving so the lookup runs against a populated list.
    // Demo users have assignmentsLoaded = true from mount (initialized to !isReal).
    // pendingQuizId is cleared only after a definitive outcome:
    //   found  → open the quiz, then clear
    //   loaded + not found → surface an error, then clear
    // Re-runs when pendingQuizId changes (new deep-link) or assignmentsLoaded flips (data ready).
    useEffect(() => {
      if (!pendingQuizId) return;
      if (!assignmentsLoaded) return; // real users: wait for Supabase assignments to resolve

      const found = assignments.find(q => q.id === pendingQuizId)
                 ?? (!isReal ? USER_QUIZ_ASSIGNMENTS_SEED.find(q => q.id === pendingQuizId) : null);

      if (found) {
        startQuiz(pendingQuizId);
      } else {
        toast.error("That quiz isn't assigned to your account or is no longer available.");
      }
      onClearPendingQuiz?.(); // clear only after definitive outcome
    }, [pendingQuizId, assignmentsLoaded]); // eslint-disable-line react-hooks/exhaustive-deps

    // Deep-link: REVIEW a specific past attempt navigated here from Learn → Completed.
    // This is read-only and NEVER starts a new attempt — it routes straight into the
    // canonical viewResults() review flow (get_quiz_review, immutable snapshot) for the
    // EXACT attempt id carried on the history row. Archived quizzes review fine because
    // the review RPC reads the immutable attempt snapshot, not the live/mutable quiz.
    // A missing attemptId still opens review-loading (viewResults resolves the attempt
    // from the pass-gated review payload) but never falls through to starting the quiz.
    // The intent is deliberately NOT cleared here: it stays persisted (App state +
    // sessionStorage) so a refresh WHILE reviewing re-mounts and restores the SAME
    // attempt. It is cleared on exit (onExitQuiz → Back to Learn) or when a quiz Start
    // supersedes it — see the mutually-exclusive App handlers — so a stale review
    // marker can never hijack a fresh Start or a mid-take refresh.
    useEffect(() => {
      if (!pendingQuizReview?.quizId) return;
      viewResults(pendingQuizReview.quizId, pendingQuizReview.attemptId ? { id: pendingQuizReview.attemptId } : null);
    }, [pendingQuizReview?.quizId, pendingQuizReview?.attemptId]); // eslint-disable-line react-hooks/exhaustive-deps

    const onComplete = (attempt) => {
      if (!isReal) {
        // Demo only — no server; keep the optimistic local results (canonical
        // seed data, rendered by QuizResultsView with its own client grading).
        setDemoAssignments(prev => prev.map(q => q.id === activeId
          ? { ...q, attempts: [...q.attempts, attempt] }
          : q
        ));
        setActiveAttempt(attempt);
        setView("results");
        return;
      }
      if (!(currentUser?.id && tenantId)) return;
      if (submittingRef.current) return;   // ignore a second Finish before the first resolves
      submittingRef.current = true;

      // Do NOT show results/pass/XP until the server confirms. Client score is
      // never treated as truth; the results screen is built from the server's
      // authoritative response + the pass-gated review (get_quiz_review).
      setView("submitting");
      submitQuizAttemptAtomicV2(tenantId, activeId, attempt.answers, takeQuiz?.questionRevision, attempt.submissionId)
        .then(async ({ data, error }) => {
          const res = interpretSubmit(data, error);
          if (res.kind === "error") {
            console.error("[ralli] submitQuizAttemptAtomicV2 failed:", error);
            toast.error("Couldn't submit your quiz. Please try again.");
            setView("taking");   // no success screen; let them retry the submit
            return;
          }
          if (res.kind === "quiz_changed") {
            // Rejected stale submission — NOTHING persisted or awarded. Show no
            // success; clear ALL cached quiz/answer/attempt state and reload the
            // latest sanitized quiz + revision (no hard refresh).
            toast.error("This quiz changed while you were taking it. Reloading the latest version.");
            setActiveAttempt(null);
            setReviewModel(null);
            setTakeQuiz(null);
            setView("list");
            loadUserQuizData?.();
            onRefreshQuizzes?.();
            return;
          }
          // status 'ok' — server-authoritative (also the idempotent replay path:
          // a lost response + retry with the SAME submissionId returns the
          // existing attempt, alreadyRecorded, with no duplicate attempt/XP).
          // The accepted score/pass is shown IMMEDIATELY; the per-question review
          // (pass-gated snapshot) loads separately and is independently retryable
          // — a review-fetch failure never loses the score and never resubmits.
          setReviewModel({
            attempt:     { score: res.score, passed: res.passed, date: fmtDate(res.attempt?.created_at ?? new Date().toISOString()) },
            points:      res.points,
            status:      "loading",
            rows:        [], reveal: false, unavailable: false,
            attemptId:   res.attempt?.id ?? null,
            fallbackAnswers: res.answers ?? [],
          });
          setView("results");
          sharedAssignmentData?.applyLocalQuizAttempt?.({
            quiz_id: activeId, score: res.score, passed: res.passed,
            answers: [], created_at: res.attempt?.created_at ?? new Date().toISOString(),
          });
          triggerReadinessUpdate(tenantId, currentUser.id);
          loadReview(res.attempt?.id ?? null);
        })
        .catch(e => {
          console.error("[ralli] submitQuizAttemptAtomicV2 failed:", e);
          toast.error("Couldn't submit your quiz. Please try again.");
          setView("taking");
        })
        .finally(() => { submittingRef.current = false; });
    };

    // Back/Exit destination. For a learner who deep-launched from Learn, onExitQuiz
    // returns to the ORIGINATING Learn context (To Do / Knowledge Base) and NEVER
    // renders the retired Quizzes dashboard. In the manager quiz-library panel (no
    // onExitQuiz) "back" means the library list, as before.
    const backToList = onExitQuiz ?? (() => setView("list"));
    const backLabel  = onExitQuiz ? "← Back to Learn" : "← Back to Quizzes";

    // ── Loading the sanitized quiz for a real learner (Start / Retake) ──
    if (view === "starting") {
      return <LoadingState rows={2} message="Loading quiz…" />;
    }

    // ── Start failed — Retry only; NEVER fall back to canonical quiz data ──
    if (view === "start_error") {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <button onClick={backToList} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0, alignSelf: "flex-start" }}>{backLabel}</button>
          <ErrorState message="We couldn't load this quiz. Please try again." onRetry={() => startQuiz(activeId)} />
        </div>
      );
    }

    // ── Reviewing a past attempt — its OWN loading/error, with a Back action.
    //    Crucially this NEVER starts or opens the quiz (unlike start_error). ──
    if (view === "review_loading") {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <button onClick={backToList} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0, alignSelf: "flex-start" }}>{backLabel}</button>
          <LoadingState rows={2} message="Loading your results…" />
        </div>
      );
    }
    if (view === "review_error") {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <button onClick={backToList} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 13, fontWeight: 600, color: C.textSub, padding: 0, alignSelf: "flex-start" }}>{backLabel}</button>
          <ErrorState message="We couldn't load these results. Please try again." onRetry={() => reviewTarget && viewResults(reviewTarget.id, reviewTarget.attempt)} />
        </div>
      );
    }

    // ── Submitting — server is grading; no results/pass/XP until it confirms ──
    if (view === "submitting") {
      return (
        <div style={{ padding: 56, textAlign: "center", background: C.white, borderRadius: 16, border: `1px solid ${C.border}` }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 6 }}>Submitting…</div>
          <p style={{ fontSize: 13, color: C.textSub, margin: 0 }}>Grading your quiz on the server. Please wait.</p>
        </div>
      );
    }

    // ── Quiz taking — sanitized quiz for real learners (no answer keys, no
    //    client feedback); demo keeps its canonical seed + teach-as-you-go. ──
    if (view === "taking" && takeQuiz) {
      return <QuizTakingView quiz={takeQuiz} onComplete={onComplete} onExit={backToList} revealFeedback={!isReal} />;
    }

    // ── Results ──
    if (view === "results") {
      if (isReal && reviewModel) {
        return (
          <SnapshotQuizReview
            quizName={activeQuiz?.title ?? activeQuiz?.name ?? "Quiz"}
            attempt={reviewModel.attempt}
            rows={reviewModel.rows}
            reveal={reviewModel.reveal}
            unavailable={reviewModel.unavailable}
            points={reviewModel.points}
            reviewStatus={reviewModel.status ?? "ready"}
            onRetryReview={() => loadReview(reviewModel.attemptId)}
            onRetake={() => retakeQuiz(activeId)}
            onBack={backToList}
          />
        );
      }
      if (!isReal && takeQuiz && activeAttempt) {
        return <QuizResultsView quiz={takeQuiz} attempt={activeAttempt} onRetake={() => retakeQuiz(activeId)} onBack={backToList} />;
      }
    }

    // ── Loading state for real users ──
    if (!assignmentsLoaded) {
      return <LoadingState rows={3} message="Loading quizzes…" />;
    }

    // ── Error state — Task 8: a failed fetch used to fall straight into the
    // empty state below; distinguish it with ErrorState + Retry. ──
    if (quizDataError) {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>Quizzes</h2>
          </div>
          <ErrorState message={quizDataError} onRetry={loadUserQuizData} />
        </div>
      );
    }

    // ── Empty state for real users with no assignments ──
    if (isReal && assignments.length === 0) {
      return (
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>Quizzes</h2>
            <p style={{ margin: "4px 0 0", fontSize: 13, color: C.textSub }}>Test your knowledge and earn XP</p>
          </div>
          <div style={{ padding: 48, textAlign: "center", background: C.white, borderRadius: 16, border: `1px solid ${C.border}` }}>
            <p style={{ fontSize: 15, fontWeight: 700, color: C.text, margin: "0 0 4px" }}>No quizzes assigned yet</p>
            <p style={{ fontSize: 13, color: C.textSub, margin: 0 }}>Your manager will assign quizzes here when they're ready.</p>
          </div>
        </div>
      );
    }

    // ── Search filter ──
    const q = search.trim().toLowerCase();
    const searchFiltered = q
      ? assignments.filter(quiz =>
          (quiz.title ?? quiz.name ?? "").toLowerCase().includes(q) ||
          (quiz.description ?? "").toLowerCase().includes(q) ||
          (quiz.track ?? "").toLowerCase().includes(q) ||
          quiz.tags?.some(t => t.includes(q))        ||
          quiz.questions?.some(qs => qs.text?.toLowerCase().includes(q))
        )
      : assignments;

    // ── Tab filter ──
    // For real users, attempt history comes from userQuizAttempts (DB-backed).
    // quiz.attempts is always [] for real users — only used as demo fallback.
    // "Done" is instance-aware for real users: resolvedStatus === "completed"
    // (a PASS at/after the LATEST assignment), NOT a lifetime passed attempt —
    // so a reassignment after an old pass correctly reappears as To Do. Demo
    // has no assignment instances, so it keeps its passed-attempt shortcut.
    const isQuizDone = (quiz) => isReal
      ? quiz.resolvedStatus === "completed"
      : (userQuizAttempts[quiz.id] ?? quiz.attempts).some(a => a.passed);

    const tabFiltered = searchFiltered.filter(quiz => {
      const isDone = isQuizDone(quiz);
      if (tab === "todo")      return !isDone;
      if (tab === "completed") return isDone;
      return true;
    });

    const todoCount      = searchFiltered.filter(q => !isQuizDone(q)).length;
    const completedCount = searchFiltered.filter(q =>  isQuizDone(q)).length;

    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 12 }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>Quizzes</h2>
            <p style={{ margin: "4px 0 0", fontSize: 13, color: C.textSub }}>Test your knowledge and earn XP</p>
          </div>
          {/* Search */}
          <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 14px", borderRadius: 10, background: C.cardBg, border: `1px solid ${C.creamBorder}`, minWidth: 240 }}>
            <span style={{ fontSize: 13, color: C.textMuted, flexShrink: 0 }}>Search</span>
            <input
              type="text" value={search} placeholder="Title, topic, tag…"
              onChange={e => setSearch(e.target.value)}
              style={{ flex: 1, border: "none", background: "transparent", fontSize: 13, color: C.text, outline: "none", fontFamily: "inherit" }}
            />
            {search && <button onClick={() => setSearch("")} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 12, color: C.textMuted, padding: 0, lineHeight: 1 }}>✕</button>}
          </div>
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: 6 }}>
          {[
            ["todo",      `To Do (${todoCount})`],
            ["completed", `Completed (${completedCount})`],
            ["all",       `All (${searchFiltered.length})`],
          ].map(([id, label]) => (
            <button key={id} onClick={() => setTab(id)} style={{
              padding: "7px 14px", borderRadius: 8,
              border: `1px solid ${tab === id ? C.orange : C.border}`,
              background: tab === id ? C.orangeLight : C.white,
              color: tab === id ? C.orange : C.textSub,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}>{label}</button>
          ))}
        </div>

        {/* Empty state */}
        {tabFiltered.length === 0 ? (
          <div style={{ padding: 48, textAlign: "center", background: C.white, borderRadius: 16, border: `1px solid ${C.border}` }}>
            <p style={{ fontSize: 15, fontWeight: 700, color: C.text, margin: "0 0 4px" }}>
              {search ? `No results for "${search}"` : tab === "completed" ? "No completed quizzes yet" : "All caught up!"}
            </p>
            <p style={{ fontSize: 13, color: C.textSub, margin: 0 }}>
              {search ? "Try a different search term." : tab === "completed" ? "Complete a quiz to see it here." : "Nothing left to do."}
            </p>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {tabFiltered.map(quiz => {
              // Real users: scope the card's state to the LATEST assignment
              // instance (quiz.scopedAttempts = attempts at/after it), so a
              // fresh reassignment reads "Start" (not "Resume/Retry") even when
              // older lifetime attempts exist, and Retry shows only for a failed
              // attempt on THIS assignment. Demo keeps its lifetime attempts.
              const attempts    = isReal ? (quiz.scopedAttempts ?? []) : quiz.attempts;
              const lastAttempt = attempts.length > 0
                ? (isReal ? attempts[0] : attempts[attempts.length - 1])
                : null;
              const isPassed    = isReal ? (quiz.resolvedStatus === "completed") : (lastAttempt?.passed ?? false);
              const hasTried    = attempts.length > 0;
              const dueStatus   = getDueStatus(quiz.dueAt);
              const progress    = getDueProgress(quiz.assignedAt, quiz.dueAt);

              return (
                <Card key={quiz.id} style={{ display: "flex", flexDirection: "column", gap: 0 }}>
                  <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 4 }}>
                        <span style={{ fontSize: 15, fontWeight: 700, color: C.text }}>{quiz.title}</span>
                        {isPassed && (
                          <span style={{ fontSize: 11, fontWeight: 700, padding: "2px 8px", borderRadius: 99, background: "#DCFCE7", color: "#166534", border: "1px solid #86EFAC" }}>Passed</span>
                        )}
                        {hasTried && !isPassed && (
                          <span style={{ fontSize: 11, fontWeight: 700, padding: "2px 8px", borderRadius: 99, background: "#FEE2E2", color: "#991B1B", border: "1px solid #FCA5A5" }}>Retry</span>
                        )}
                      </div>
                      {quiz.description && <p style={{ margin: "0 0 6px", fontSize: 12, color: C.textSub }}>{quiz.description}</p>}
                      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                        <span style={{ fontSize: 12, color: C.textMuted }}>{quiz.track}</span>
                        <span style={{ fontSize: 12, color: C.textMuted }}>{questionCountOf(quiz)} questions</span>
                        <span style={{ fontSize: 12, color: diffColors[quiz.difficulty] ?? C.textMuted, fontWeight: 700 }}>{quiz.difficulty}</span>
                        <span style={{ fontSize: 12, fontWeight: 700, color: C.orange }}>+{quiz.xp} XP</span>
                        {lastAttempt && <span style={{ fontSize: 12, color: C.textMuted }}>Last score: {lastAttempt.score}%</span>}
                      </div>
                    </div>

                    {/* Actions */}
                    <div style={{ display: "flex", gap: 8, flexShrink: 0, alignItems: "center" }}>
                      {isPassed && (
                        <button onClick={() => viewResults(quiz.id, lastAttempt)} style={{ padding: "8px 14px", borderRadius: 8, border: `1px solid ${C.border}`, background: C.cardBg, fontSize: 12, fontWeight: 600, cursor: "pointer", color: C.text }}>
                          View Results
                        </button>
                      )}
                      <button onClick={() => hasTried ? retakeQuiz(quiz.id) : startQuiz(quiz.id)} style={{
                        padding: "8px 18px", borderRadius: 8, border: "none",
                        background: isPassed ? C.orange + "CC" : C.orange,
                        color: "#fff", fontSize: 13, fontWeight: 700, cursor: "pointer",
                      }}>
                        {isPassed ? "Retake" : hasTried ? "Resume →" : "Start →"}
                      </button>
                    </div>
                  </div>

                  {/* Due date row — only for todo/all tabs with a due date */}
                  {quiz.dueAt && !isPassed && (
                    <div style={{ marginTop: 14, paddingTop: 14, borderTop: `1px solid ${C.creamBorder}` }}>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
                        <span style={{ fontSize: 12, fontWeight: 700, color: dueStatus?.color ?? C.textSub }}>{dueStatus?.label}</span>
                        <span style={{ fontSize: 11, color: C.textMuted }}>Due {quiz.dueAt}</span>
                      </div>
                      <div style={{ height: 5, borderRadius: 99, background: C.muted, overflow: "hidden" }}>
                        <div style={{
                          height: "100%", borderRadius: 99,
                          background: progress >= 100 ? C.red : progress >= 80 ? C.orange : C.trueGreen,
                          width: `${progress}%`, transition: "width 0.3s",
                        }} />
                      </div>
                    </div>
                  )}
                </Card>
              );
            })}
          </div>
        )}
      </div>
    );
  }

  // ── ADMIN VIEW ────────────────────────────────────────────────────────────
  const [assignModal, setAssignModal]   = useState(null); // null | quiz object
  const [adminTab,    setAdminTab]      = useState("library"); // "library" | "tracking"
  const [refreshKey,  setRefreshKey]    = useState(0); // bumped after a new assignment so tracking refetches

  // ── Normalized quiz tags (058/059) for Library display + filtering ────────
  const tagCaps = tagCapabilities(currentUser?.role);
  const tagsEnabled = isReal && !!tenantId && tagCaps.canAssign;
  const [tagCatalog, setTagCatalog]     = useState([]);
  const [tagModelByQuiz, setTagModel]   = useState(new Map());
  const [tagFilter, setTagFilter]       = useState({ kind: "all" });
  const [showTagManager, setShowTagManager] = useState(false);
  const [tagLoading, setTagLoading]     = useState(false);

  // ONE shared loader for the whole surface (catalog + per-quiz model). Used by
  // the mount effect AND passed to the Tag manager as its authoritative refresh,
  // so a create/rename/archive/restore/merge updates cards, filters and the
  // modal from a single store — no duplicate tag state, no reopen needed.
  const loadTagData = useCallback(async () => {
    if (!tagsEnabled) return;
    setTagLoading(true);
    const [{ data: catalog }, { data: mapRows }, { data: cls }] = await Promise.all([
      listTenantQuizTags(tenantId, { includeArchived: true }),
      listQuizTagMap(tenantId),
      listQuizClassification(tenantId),
    ]);
    setTagCatalog(catalog ?? []);
    const byQuiz = new Map();
    for (const q of (cls ?? [])) byQuiz.set(q.id, { classifiedAt: q.tags_classified_at ?? null, tagIds: [] });
    for (const r of (mapRows ?? [])) {
      const e = byQuiz.get(r.quiz_id) ?? { classifiedAt: null, tagIds: [] };
      e.tagIds = [...e.tagIds, r.tag_id];
      byQuiz.set(r.quiz_id, e);
    }
    setTagModel(byQuiz);
    setTagLoading(false);
  }, [tagsEnabled, tenantId]);

  useEffect(() => { loadTagData(); }, [loadTagData, quizzes.length]);

  const tagCatalogById = new Map(tagCatalog.map(t => [t.id, t]));
  const tagUsage = tagUsageCounts([...tagModelByQuiz.values()].flatMap(m => m.tagIds.map(id => ({ tag_id: id }))));
  const activeCatalog = tagCatalog.filter(t => t.status === "active");
  const libraryQuizzes = tagsEnabled ? filterQuizzesByTag(quizzes, tagModelByQuiz, tagFilter) : quizzes;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: C.text }}>Quizzes</h2>
          <p style={{ margin: "4px 0 0", fontSize: 13, color: C.textSub }}>
            {adminTab === "library"
              ? `${quizzes.length} quiz${quizzes.length !== 1 ? "zes" : ""} — use these in ralli sessions`
              : "Assignment status and results for every rep"}
          </p>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          {tagsEnabled && adminTab === "library" && (
            <button onClick={() => setShowTagManager(true)} style={{
              display: "flex", alignItems: "center", gap: 6, padding: "10px 16px",
              borderRadius: 12, border: `1px solid ${C.border}`, cursor: "pointer",
              fontSize: 13, fontWeight: 700, color: C.text, background: C.white,
            }}>{tagCaps.canGovern ? "Manage Tags" : "View Tags"}</button>
          )}
          {canCreate && adminTab === "library" && (
            <button onClick={() => { onEditQuiz(null); onNav("rankd-quiz-builder"); }} style={{
              display: "flex", alignItems: "center", gap: 8, padding: "10px 20px",
              borderRadius: 12, border: "none", cursor: "pointer",
              fontSize: 13, fontWeight: 700, color: "#fff", background: C.orange,
            }}>✚ Create Quiz</button>
          )}
        </div>
      </div>

      {/* Library / Assignments tab switcher */}
      <div style={{ display: "flex", gap: 6 }}>
        {[["library", "Library"], ["tracking", "Assignments"]].map(([id, label]) => (
          <button key={id} onClick={() => setAdminTab(id)} style={{
            padding: "8px 16px", borderRadius: 8,
            border: `1px solid ${adminTab === id ? C.orange : C.border}`,
            background: adminTab === id ? C.orangeLight : C.white,
            color: adminTab === id ? C.orange : C.textSub,
            fontSize: 13, fontWeight: 700, cursor: "pointer",
          }}>{label}</button>
        ))}
      </div>

      {adminTab === "library" ? (
        quizzes.length === 0 ? (
          <div style={{ padding: 60, borderRadius: 16, border: `2px dashed ${C.border}`, textAlign: "center", background: C.white }}>
            <p style={{ fontSize: 16, fontWeight: 700, color: C.text, margin: "0 0 6px" }}>No quizzes yet</p>
            <p style={{ fontSize: 13, color: C.textSub, margin: "0 0 24px" }}>Build quizzes here, then launch them as ralli sessions</p>
            {canCreate && (
              <button onClick={() => { onEditQuiz(null); onNav("rankd-quiz-builder"); }} style={{
                padding: "12px 28px", borderRadius: 14, border: "none", cursor: "pointer",
                fontSize: 14, fontWeight: 700, background: C.orange, color: "#fff",
              }}>Build Your First Quiz →</button>
            )}
          </div>
        ) : (
          <>
            {/* Stable-ID tag filters (honest states; never invents tags) */}
            {tagsEnabled && (
              <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 6 }}>
                {[
                  { key: "all", label: `All (${quizzes.length})`, filter: { kind: "all" } },
                ].map(chip => {
                  const on = tagFilter.kind === chip.filter.kind && !tagFilter.tagId;
                  return (
                    <button key={chip.key} onClick={() => setTagFilter(chip.filter)} style={{
                      padding: "6px 12px", borderRadius: 999, fontSize: 12, fontWeight: 700, cursor: "pointer",
                      border: `1px solid ${on ? C.orange : C.border}`, background: on ? C.orangeLight : C.white,
                      color: on ? C.orange : C.textSub }}>{chip.label}</button>
                  );
                })}
                {activeCatalog.map(t => {
                  const on = tagFilter.kind === "tag" && tagFilter.tagId === t.id;
                  return (
                    <button key={t.id} onClick={() => setTagFilter({ kind: "tag", tagId: t.id })} style={{
                      padding: "6px 12px", borderRadius: 999, fontSize: 12, fontWeight: 700, cursor: "pointer",
                      border: `1px solid ${on ? C.orange : C.border}`, background: on ? C.orangeLight : C.white,
                      color: on ? C.orange : C.textSub }}>{t.label} · {tagUsage.get(t.id) || 0}</button>
                  );
                })}
              </div>
            )}
            {tagsEnabled && libraryQuizzes.length === 0 ? (
              <div style={{ padding: 40, borderRadius: 16, border: `2px dashed ${C.border}`, textAlign: "center", background: C.white }}>
                <p style={{ fontSize: 14, fontWeight: 700, color: C.text, margin: 0 }}>No quizzes match this filter.</p>
              </div>
            ) : (
              <QuizLibraryGrid
                quizzes={libraryQuizzes}
                tagModelByQuiz={tagsEnabled ? tagModelByQuiz : null}
                tagCatalogById={tagCatalogById}
                onEditQuiz={onEditQuiz}
                onNav={onNav}
                onArchiveQuiz={onArchiveQuiz}
                onRestoreQuiz={onRestoreQuiz}
                onToggleFavorite={onToggleFavorite}
                onToggleActive={onToggleActive}
                onAssign={canAssign ? (quiz) => setAssignModal(quiz) : null}
                canEdit={canEdit}
                canDelete={canDelete}
                canAssign={canAssign}
                canLaunch={canLaunch}
                onLaunchQuiz={canLaunch && onLaunchQuiz ? (quiz) => onLaunchQuiz({
                  code:          String(Math.floor(100000 + Math.random() * 900000)),
                  name:          quiz.name,
                  quizId:        quiz.id,
                  questionCount: quiz.questions?.length ?? 0,
                  status:        "waiting",
                  playerCount:   0,
                  demoMode:      false,
                  players:       [],
                }) : null}
              />
            )}
          </>
        )
      ) : (
        <QuizTrackingPanel
          quizzes={quizzes}
          orgUsers={orgUsers}
          tenantId={tenantId}
          isReal={isReal}
          refreshKey={refreshKey}
          canAssign={canAssign}
          onAssign={(quiz) => setAssignModal(quiz)}
        />
      )}

      {/* Assign modal */}
      {assignModal && (
        <AssignContentModal
          contentType="quiz"
          contentId={assignModal.id}
          content={assignModal}
          orgUsers={orgUsers}
          orgs={orgs}
          currentUser={currentUser}
          tenantId={tenantId}
          isReal={isReal}
          onAssign={async (assignment) => {
            let blocked = false;
            if (onAssignQuiz) {
              const result = await onAssignQuiz(assignment);
              blocked = result?.blocked ?? false;
            }
            // Keep the modal open on a blocked individual assignment so the
            // manager can see the error toast and adjust (different user, wait, etc.)
            // instead of losing their in-progress picks.
            if (blocked) return;
            setAssignModal(null);
            setRefreshKey(k => k + 1); // refetch tracking panel so the new assignment shows immediately
          }}
          onClose={() => setAssignModal(null)}
        />
      )}

      {/* Shared taxonomy management surface */}
      {showTagManager && tagsEnabled && (
        <TagManagerModal
          tenantId={tenantId}
          caps={tagCaps}
          catalog={tagCatalog}
          catalogLoading={tagLoading}
          onRefresh={loadTagData}
          onClose={() => setShowTagManager(false)}
        />
      )}
    </div>
  );
}

